    fn temp_db_path(test_name: &str) -> PathBuf {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        std::env::temp_dir().join(format!(
            "rustaxa-consensus-final-chain-{test_name}-{}-{nanos}",
            std::process::id()
        ))
    }

    #[test]
    fn dpos_contract_errors_render_exact_legacy_messages() {
        let cases = [
            (
                DposContractError::NonExistentValidator,
                "Validator does not exist",
            ),
            (
                DposContractError::NonExistentDelegation,
                "Delegation does not exist",
            ),
            (
                DposContractError::ExistentUndelegation,
                "Undelegation already exist",
            ),
            (
                DposContractError::NonExistentUndelegation,
                "Undelegation does not exist",
            ),
            (
                DposContractError::LockedUndelegation,
                "Undelegation is not yet ready to be withdrawn",
            ),
            (
                DposContractError::ExistentValidator,
                "Validator already exist",
            ),
            (
                DposContractError::SameValidator,
                "From and to validators are the same",
            ),
            (
                DposContractError::InvalidRedelegation,
                "Redelegation has to be more than 0",
            ),
            (
                DposContractError::ValidatorsMaxStakeExceeded,
                "Validator's max stake exceeded",
            ),
            (
                DposContractError::InsufficientDelegation,
                "Insufficient delegation",
            ),
            (
                DposContractError::WrongProof,
                "Wrong proof, validator address could not be recovered",
            ),
            (
                DposContractError::WrongOwnerAcc,
                "This account is not owner of specified validator",
            ),
            (
                DposContractError::WrongVrfKey,
                "Wrong vrf key specified in validator arguments",
            ),
            (
                DposContractError::ForbiddenCommissionChange,
                "Forbidden commission change",
            ),
            (
                DposContractError::CommissionOverflow,
                "Commission is bigger than maximum value",
            ),
            (
                DposContractError::MaxEndpointLengthExceeded,
                "Max endpoint length exceeded",
            ),
            (
                DposContractError::MaxDescriptionLengthExceeded,
                "Max description length exceeded",
            ),
            (
                DposContractError::MethodNotSupported,
                "Method not supported",
            ),
            (
                DposContractError::LegacyMessage("recovery failed".to_owned()),
                "recovery failed",
            ),
        ];

        for (error, expected) in cases {
            assert_eq!(error.legacy_message(), expected);
        }

        let validator = [0xab; 20];
        assert_eq!(
            DposContractError::ClaimAllValidator {
                source: Box::new(DposContractError::NonExistentDelegation),
                validator,
            }
            .legacy_message(),
            "Delegation does not exist -> validator: 0xabababababababababababababababababababab"
        );
    }

    #[test]
    fn dpos_apply_outcome_keeps_error_separate_from_status_logs_and_return_bytes() {
        let log = ReceiptLog {
            address: [0x11; 20],
            topics: vec![[0x22; 32]],
            data: vec![0x33],
        };
        let success = DposApplyOutcome::success_with(vec![log.clone()], vec![0x44]);
        assert_eq!(success.status_code, 1);
        assert_eq!(success.logs, vec![log]);
        assert_eq!(success.code_retval, vec![0x44]);
        assert_eq!(success.contract_error, None);

        let untyped = DposApplyOutcome::contract_failure();
        assert_eq!(untyped.status_code, 0);
        assert!(untyped.logs.is_empty());
        assert!(untyped.code_retval.is_empty());
        assert_eq!(untyped.contract_error, None);

        let typed =
            DposApplyOutcome::mutation_contract_failure(DposContractError::NonExistentValidator);
        assert_eq!(typed.status_code, 0);
        assert!(typed.logs.is_empty());
        assert!(typed.code_retval.is_empty());
        assert_eq!(
            typed.contract_error,
            Some(DposContractError::NonExistentValidator)
        );
    }

    #[test]
    fn dpos_delegate_reports_maximum_before_minimum_when_both_fail() {
        let path = temp_db_path("dpos-typed-delegate-error-order");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator = [0x41; 20];
        let delegator = [0x42; 20];
        let mut final_chain = new_final_chain_with_dpos(
            storage.clone(),
            vec![genesis_validator(validator, U256::from(10u64))],
            U256::one(),
            U256::one(),
            U256::from(10u64),
        );
        final_chain.dpos_minimum_deposit = u256_to_big_endian(U256::from(5u64));
        let mut snapshot = final_chain.dpos_snapshot(0).unwrap();
        let snapshot_before = snapshot.clone();
        let mut accounts = HashMap::new();

        let outcome = final_chain
            .apply_dpos_delegate(
                &mut snapshot,
                &mut accounts,
                delegator,
                validator,
                u256_to_big_endian(U256::one()),
            )
            .unwrap();

        assert_eq!(
            outcome.contract_error,
            Some(DposContractError::ValidatorsMaxStakeExceeded)
        );
        assert_eq!(snapshot, snapshot_before);
        assert!(accounts.is_empty());

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn dpos_undelegate_v2_aggregate_stake_underflow_is_hard_error() {
        let path = temp_db_path("dpos-typed-v2-hard-underflow");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator = [0x51; 20];
        let final_chain = new_final_chain_with_dpos(
            storage.clone(),
            vec![genesis_validator(validator, U256::from(10u64))],
            U256::one(),
            U256::one(),
            U256::from(100u64),
        );
        let mut snapshot = final_chain.dpos_snapshot(0).unwrap();
        snapshot
            .total_stakes
            .insert(validator, u256_to_big_endian(U256::from(5u64)));
        let snapshot_before = snapshot.clone();
        let mut accounts = HashMap::new();

        let error = final_chain
            .apply_dpos_undelegate_v2(
                &mut snapshot,
                &mut accounts,
                validator,
                validator,
                u256_to_big_endian(U256::from(6u64)),
                0,
            )
            .unwrap_err();

        assert!(
            error
                .to_string()
                .contains("stake underflows on undelegate V2")
        );
        assert_eq!(snapshot, snapshot_before);
        assert!(accounts.is_empty());

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn dpos_undelegate_v2_preflight_reports_expected_failures_in_order() {
        struct Case {
            name: &'static str,
            delegator: [u8; 20],
            input_validator: [u8; 20],
            genesis_validator: [u8; 20],
            genesis_stake: u64,
            amount: u64,
            minimum_deposit: Option<u64>,
            expected_error: DposContractError,
            legacy_message: &'static str,
        }

        let cases = [
            Case {
                name: "missing-validator",
                delegator: [0xAA; 20],
                input_validator: [0x53; 20],
                genesis_validator: [0x52; 20],
                genesis_stake: 10_000u64,
                amount: 1u64,
                minimum_deposit: None,
                expected_error: DposContractError::NonExistentValidator,
                legacy_message: "Validator does not exist",
            },
            Case {
                name: "missing-delegation",
                delegator: [0x55; 20],
                input_validator: [0x54; 20],
                genesis_validator: [0x54; 20],
                genesis_stake: 10_000u64,
                amount: 1u64,
                minimum_deposit: None,
                expected_error: DposContractError::NonExistentDelegation,
                legacy_message: "Delegation does not exist",
            },
            Case {
                name: "amount-above-delegation",
                delegator: [0x56; 20],
                input_validator: [0x56; 20],
                genesis_validator: [0x56; 20],
                genesis_stake: 10_000u64,
                amount: 20_000u64,
                minimum_deposit: None,
                expected_error: DposContractError::InsufficientDelegation,
                legacy_message: "Insufficient delegation",
            },
            Case {
                name: "minimum-deposit-remainder",
                delegator: [0x57; 20],
                input_validator: [0x57; 20],
                genesis_validator: [0x57; 20],
                genesis_stake: 20u64,
                amount: 11u64,
                minimum_deposit: Some(10u64),
                expected_error: DposContractError::InsufficientDelegation,
                legacy_message: "Insufficient delegation",
            },
        ];

        for case in cases {
            let path = temp_db_path(&format!("dpos-typed-v2-{}", case.name));
            let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
            let mut final_chain = new_final_chain_with_dpos(
                storage.clone(),
                vec![genesis_validator(
                    case.genesis_validator,
                    U256::from(case.genesis_stake),
                )],
                U256::one(),
                U256::one(),
                U256::from(100_000u64),
            );
            if let Some(deposit) = case.minimum_deposit {
                final_chain.dpos_minimum_deposit = u256_to_big_endian(U256::from(deposit));
            }

            let mut snapshot = final_chain.dpos_snapshot(0).unwrap();
            let snapshot_before = snapshot.clone();
            let mut accounts = HashMap::new();

            let outcome = final_chain
                .apply_dpos_undelegate_v2(
                    &mut snapshot,
                    &mut accounts,
                    case.delegator,
                    case.input_validator,
                    u256_to_big_endian(U256::from(case.amount)),
                    0,
                )
                .unwrap();

            assert_eq!(outcome.contract_error, Some(case.expected_error.clone()));
            assert_eq!(case.expected_error.legacy_message(), case.legacy_message);
            assert_eq!(snapshot, snapshot_before);
            assert!(accounts.is_empty());

            drop(final_chain);
            drop(storage);
            let _ = std::fs::remove_dir_all(path);
        }
    }

    #[test]
    fn dpos_v2_request_consumption_errors_are_ordered_and_state_is_unchanged() {
        enum RequestCall {
            Confirm,
            Cancel,
        }

        struct Case {
            name: &'static str,
            call: RequestCall,
            delegator: [u8; 20],
            validator: [u8; 20],
            request_id: u64,
            block_number: u64,
            expected: DposContractError,
            expected_message: &'static str,
        }

        let path = temp_db_path("dpos-typed-v2-consumption-errors");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let delegator = [0xA1; 20];
        let wrong_delegator = [0xA2; 20];
        let active_validator = [0xA3; 20];
        let absent_validator = [0xA4; 20];
        let final_chain = new_final_chain_with_dpos(
            storage.clone(),
            vec![genesis_validator(active_validator, U256::from(10u64))],
            U256::one(),
            U256::one(),
            U256::from(100u64),
        );
        let mut snapshot = final_chain.dpos_snapshot(0).unwrap();
        let active_request_id = create_undelegation_v2(
            &mut snapshot,
            delegator,
            active_validator,
            vec![1u8; 32],
            10,
        )
        .unwrap();
        create_undelegation_v2(
            &mut snapshot,
            delegator,
            absent_validator,
            vec![2u8; 32],
            10,
        )
        .unwrap();
        let snapshot_before = snapshot.clone();

        let cases = [
            Case {
                name: "confirm_missing_id",
                call: RequestCall::Confirm,
                delegator,
                validator: active_validator,
                request_id: active_request_id + 1,
                block_number: 9,
                expected: DposContractError::NonExistentUndelegation,
                expected_message: "Undelegation does not exist",
            },
            Case {
                name: "confirm_wrong_caller",
                call: RequestCall::Confirm,
                delegator: wrong_delegator,
                validator: active_validator,
                request_id: active_request_id,
                block_number: 9,
                expected: DposContractError::NonExistentUndelegation,
                expected_message: "Undelegation does not exist",
            },
            Case {
                name: "confirm_locked",
                call: RequestCall::Confirm,
                delegator,
                validator: active_validator,
                request_id: active_request_id,
                block_number: 9,
                expected: DposContractError::LockedUndelegation,
                expected_message: "Undelegation is not yet ready to be withdrawn",
            },
            Case {
                name: "cancel_missing_id",
                call: RequestCall::Cancel,
                delegator,
                validator: active_validator,
                request_id: 99,
                block_number: 0,
                expected: DposContractError::NonExistentUndelegation,
                expected_message: "Undelegation does not exist",
            },
            Case {
                name: "cancel_terminally_absent_validator",
                call: RequestCall::Cancel,
                delegator,
                validator: absent_validator,
                request_id: 2,
                block_number: 0,
                expected: DposContractError::NonExistentValidator,
                expected_message: "Validator does not exist",
            },
        ];

        for case in cases {
            let mut working_snapshot = snapshot_before.clone();
            let mut accounts = HashMap::new();

            let outcome = match case.call {
                RequestCall::Confirm => final_chain.apply_dpos_confirm_undelegate_v2(
                    &mut working_snapshot,
                    &mut accounts,
                    case.delegator,
                    case.validator,
                    case.request_id,
                    case.block_number,
                ),
                RequestCall::Cancel => final_chain.apply_dpos_cancel_undelegate_v2(
                    &mut working_snapshot,
                    &mut accounts,
                    case.delegator,
                    case.validator,
                    case.request_id,
                ),
            }
            .unwrap();

            assert_eq!(
                outcome.contract_error,
                Some(case.expected.clone()),
                "{} contract_error mismatch",
                case.name
            );
            assert_eq!(
                case.expected.legacy_message(),
                case.expected_message,
                "{} legacy message mismatch",
                case.name
            );
            assert_eq!(working_snapshot, snapshot_before, "{} snapshot", case.name);
            assert!(accounts.is_empty(), "{} staging state", case.name);
        }

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_fails_undelegate_v2_status_zero_and_continues_same_sender() {
        struct Case {
            name: &'static str,
            sender: [u8; 20],
            recipient: [u8; 20],
            genesis_validator: [u8; 20],
            input_validator: [u8; 20],
            genesis_stake: u64,
            amount: u64,
            minimum_deposit: Option<u64>,
        }

        let cases = [
            Case {
                name: "missing-validator",
                sender: [0xA0; 20],
                recipient: [0xA1; 20],
                genesis_validator: [0xA2; 20],
                input_validator: [0xA3; 20],
                genesis_stake: 10_000u64,
                amount: 1_000u64,
                minimum_deposit: None,
            },
            Case {
                name: "missing-delegation",
                sender: [0xB0; 20],
                recipient: [0xB1; 20],
                genesis_validator: [0xB2; 20],
                input_validator: [0xB2; 20],
                genesis_stake: 10_000u64,
                amount: 1_000u64,
                minimum_deposit: None,
            },
            Case {
                name: "amount-above-delegation",
                sender: [0xC0; 20],
                recipient: [0xC1; 20],
                genesis_validator: [0xC0; 20],
                input_validator: [0xC0; 20],
                genesis_stake: 10_000u64,
                amount: 20_000u64,
                minimum_deposit: None,
            },
            Case {
                name: "minimum-deposit-remainder",
                sender: [0xD0; 20],
                recipient: [0xD1; 20],
                genesis_validator: [0xD0; 20],
                input_validator: [0xD0; 20],
                genesis_stake: 20u64,
                amount: 11u64,
                minimum_deposit: Some(10u64),
            },
        ];

        for case in cases {
            let first_period = 1u64;
            let second_period = 2u64;
            let path = temp_db_path(&format!("finalize-dpos-undelegate-v2-{}", case.name));
            let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
            let signing_key = SigningKey::from_slice(&[72u8; 32]).unwrap();
            let first_pbft = signed_pbft_block(&signing_key, first_period, 271);
            let second_pbft = signed_pbft_block(&signing_key, second_period, 272);
            let failed_undelegate_tx = test_transaction(
                0xF1,
                case.sender,
                Some(DPOS_CONTRACT_ADDRESS),
                0,
                U256::zero(),
                U256::one(),
                100_000,
                undelegate_v2_input(case.input_validator, U256::from(case.amount)),
                vec![0xc1, 0xF1],
            );
            let transfer_tx = test_transaction(
                0xF2,
                case.sender,
                Some(case.recipient),
                1,
                U256::from(5_000u64),
                U256::one(),
                intrinsic_gas(&vec![], false).unwrap(),
                vec![],
                vec![0xc1, 0xF2],
            );

            let config = GenesisDposConfig {
                eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
                vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
                validator_maximum_stake: u256_to_big_endian(U256::from(100_000u64)),
                minimum_deposit: vec![],
                commission_change_delta: 0,
                commission_change_frequency: 0,
                delegation_delay: 0,
                dag_vdf_sortition_total_vote_count_until_period: 0,
            };
            let rewards_config = FinalChainRewardsConfig {
                magnolia_period: 10,
                aspen_part_one_period: u64::MAX,
                ..Default::default()
            };
            let mut final_chain = FinalChain::new_with_rewards_config(
                storage.clone(),
                200_000,
                0,
                vec![genesis_account(case.sender, U256::from(1_000_000u64))],
                vec![genesis_validator(
                    case.genesis_validator,
                    U256::from(case.genesis_stake),
                )],
                config,
                rewards_config,
            )
            .unwrap();
            if let Some(deposit) = case.minimum_deposit {
                final_chain.dpos_minimum_deposit = u256_to_big_endian(U256::from(deposit));
            }

            let failed_gas =
                expected_native_contract_tx_gas(&final_chain, second_period, &failed_undelegate_tx);
            let transfer_gas = intrinsic_gas(&transfer_tx.data, false).unwrap();
            write_period_data(&storage, first_period, &first_pbft, &[]);
            write_period_data(
                &storage,
                second_period,
                &second_pbft,
                &[failed_undelegate_tx.rlp.clone(), transfer_tx.rlp.clone()],
            );

            final_chain
                .finalize_block(first_pbft, vec![], vec![])
                .unwrap();
            let mut snapshot_before = final_chain.dpos_snapshot(first_period).unwrap();
            snapshot_before
                .reward_reference_graph
                .next_block(second_period)
                .unwrap();
            let sender_balance_before = balance_of(&final_chain, case.sender);
            let contract_balance_before = balance_of(&final_chain, DPOS_CONTRACT_ADDRESS);

            let (header_rlp, receipts) = final_chain
                .finalize_block(
                    second_pbft,
                    vec![failed_undelegate_tx.clone(), transfer_tx.clone()],
                    vec![],
                )
                .unwrap();
            let snapshot_after = final_chain.dpos_snapshot(second_period).unwrap();

            assert_eq!(receipts.len(), 2);
            assert_eq!(receipt_fields(&receipts[0]), (0, failed_gas, failed_gas));
            assert_eq!(
                receipt_fields(&receipts[1]),
                (1, transfer_gas, failed_gas + transfer_gas)
            );
            assert!(receipt_logs(&receipts[0]).is_empty());
            assert!(receipt_logs(&receipts[1]).is_empty());
            assert_eq!(snapshot_before, snapshot_after);
            assert_eq!(final_chain.account(case.sender).unwrap().unwrap().nonce, 2);
            assert_eq!(
                balance_of(&final_chain, case.sender),
                sender_balance_before
                    - U256::from(failed_gas + transfer_gas)
                    - U256::from(5_000u64)
            );
            assert_eq!(
                balance_of(&final_chain, DPOS_CONTRACT_ADDRESS),
                contract_balance_before
            );
            assert_eq!(
                balance_of(&final_chain, case.recipient),
                U256::from(5_000u64)
            );
            let header = Rlp::new(&header_rlp);
            let bloom: Vec<u8> = header.val_at(6).unwrap();
            assert!(bloom.iter().all(|byte| *byte == 0));

            drop(final_chain);
            drop(storage);
            let _ = std::fs::remove_dir_all(path);
        }
    }

    #[test]
    fn dpos_claim_all_contextualizes_missing_delegation_before_mutation() {
        let path = temp_db_path("dpos-typed-claim-all-context");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let delegator = [0x61; 20];
        let validator = [0x62; 20];
        let final_chain = new_final_chain_with_dpos(
            storage.clone(),
            vec![],
            U256::one(),
            U256::one(),
            U256::from(100u64),
        );
        let mut snapshot = final_chain.dpos_snapshot(0).unwrap();
        snapshot
            .delegator_validators
            .insert(delegator, vec![validator]);
        let snapshot_before = snapshot.clone();
        let mut accounts = HashMap::new();

        let outcome = final_chain
            .apply_dpos_claim_all_rewards(&mut snapshot, &mut accounts, delegator, None)
            .unwrap();

        let expected = DposContractError::ClaimAllValidator {
            source: Box::new(DposContractError::NonExistentDelegation),
            validator,
        };
        assert_eq!(outcome.contract_error, Some(expected));
        assert_eq!(snapshot, snapshot_before);
        assert!(accounts.is_empty());

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn dpos_claim_all_preserves_first_hard_error_before_later_business_error() {
        let path = temp_db_path("dpos-typed-claim-all-first-error");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let delegator = [0x11; 20];
        let first_validator = [0x22; 20];
        let missing_validator = [0x63; 20];
        let final_chain = new_final_chain(storage.clone(), 200_000, 0, Vec::new(), Vec::new());
        let mut snapshot = sample_dpos_snapshot_with_undelegations();
        snapshot
            .reward_reference_graph
            .delete_cursor(&first_validator, &delegator)
            .unwrap();
        snapshot
            .delegator_validators
            .get_mut(&delegator)
            .unwrap()
            .push(missing_validator);
        let snapshot_before = snapshot.clone();
        let mut accounts = HashMap::new();

        let error = final_chain
            .apply_dpos_claim_all_rewards(&mut snapshot, &mut accounts, delegator, None)
            .unwrap_err();

        assert!(error.to_string().contains("missing cursor"));
        assert_eq!(snapshot, snapshot_before);
        assert!(accounts.is_empty());

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn dpos_registration_proof_separates_recovery_errors_from_wrong_proof() {
        let validator = [0x71; 20];
        assert_eq!(
            validate_dpos_registration_proof(&[0u8; 64], validator).unwrap(),
            DposRegistrationProofValidation::WrongProof
        );

        let mut invalid_recovery_id = [0u8; 65];
        invalid_recovery_id[64] = 26;
        assert_eq!(
            validate_dpos_registration_proof(&invalid_recovery_id, validator).unwrap(),
            DposRegistrationProofValidation::RecoveryError(
                "calculated Rx is larger than curve P".to_owned()
            )
        );

        let mut invalid_signature = [0u8; 65];
        invalid_signature[64] = 27;
        assert_eq!(
            validate_dpos_registration_proof(&invalid_signature, validator).unwrap(),
            DposRegistrationProofValidation::RecoveryError("invalid square root".to_owned())
        );

        let signing_key = SigningKey::from_slice(&[0x73; 32]).unwrap();
        let signed_validator: [u8; 20] = address_from_signing_key(&signing_key).into();
        let mut proof = register_validator_proof(&signing_key, signed_validator, None);
        assert_eq!(
            validate_dpos_registration_proof(&proof, signed_validator).unwrap(),
            DposRegistrationProofValidation::Valid
        );
        proof[64] = proof[64].checked_add(4).unwrap();
        assert_eq!(
            validate_dpos_registration_proof(&proof, signed_validator).unwrap(),
            DposRegistrationProofValidation::Valid
        );

        let curve_order = BigUint::parse_bytes(
            b"FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141",
            16,
        )
        .unwrap();
        let curve_order_bytes = curve_order.to_bytes_be();
        let mut non_invertible_r = [0u8; 65];
        non_invertible_r[..32].copy_from_slice(&curve_order_bytes);
        non_invertible_r[63] = 1;
        non_invertible_r[64] = 27;
        assert!(
            validate_dpos_registration_proof(&non_invertible_r, validator)
                .unwrap_err()
                .to_string()
                .contains("no modular inverse")
        );

        let identity_hash = keccak256(&[0u8; 64]);
        let mut identity_validator = [0u8; 20];
        identity_validator.copy_from_slice(&identity_hash.as_bytes()[12..]);
        let generator = ProjectivePoint::GENERATOR
            .to_affine()
            .to_encoded_point(false);
        let mut identity_proof = [0u8; 65];
        identity_proof[..32].copy_from_slice(&generator.as_bytes()[1..33]);
        identity_proof[32..64].copy_from_slice(keccak256(&identity_validator).as_bytes());
        identity_proof[64] = 27 + (generator.as_bytes()[64] & 1);
        assert_eq!(
            validate_dpos_registration_proof(&identity_proof, identity_validator).unwrap(),
            DposRegistrationProofValidation::Valid
        );

        let mut zero_s_accepted = false;
        for private_key in 1u8..=64 {
            let mut private_key_bytes = [0u8; 32];
            private_key_bytes[31] = private_key;
            let signing_key = SigningKey::from_slice(&private_key_bytes).unwrap();
            let validator: [u8; 20] = address_from_signing_key(&signing_key).into();
            let message = keccak256(&validator);
            let message_scalar = BigUint::from_bytes_be(message.as_bytes()) % &curve_order;
            let mut message_word = [0u8; 32];
            let message_bytes = message_scalar.to_bytes_be();
            message_word[32 - message_bytes.len()..].copy_from_slice(&message_bytes);
            let message_scalar = Option::<Scalar>::from(Scalar::from_repr(message_word.into()))
                .expect("reduced test message scalar");
            let private_key_scalar =
                Option::<Scalar>::from(Scalar::from_repr(private_key_bytes.into()))
                    .expect("valid test private key scalar");
            let r = -(message_scalar
                * Option::<Scalar>::from(private_key_scalar.invert())
                    .expect("valid test private key inverse"));
            let r_bytes: [u8; 32] = r.to_bytes().into();
            let mut compressed_r = [0u8; 33];
            compressed_r[0] = 2;
            compressed_r[1..].copy_from_slice(&r_bytes);
            if VerifyingKey::from_sec1_bytes(&compressed_r).is_err() {
                continue;
            }

            let mut zero_s_proof = [0u8; 65];
            zero_s_proof[..32].copy_from_slice(&r_bytes);
            zero_s_proof[64] = 27;
            assert_eq!(
                validate_dpos_registration_proof(&zero_s_proof, validator).unwrap(),
                DposRegistrationProofValidation::Valid
            );
            zero_s_accepted = true;
            break;
        }
        assert!(
            zero_s_accepted,
            "test could not construct a btcec zero-S proof"
        );
    }

    #[test]
    fn dpos_dispatch_types_only_named_method_not_supported_failures() {
        let owner = [0x72; 20];
        assert!(matches!(
            decode_dpos_transaction_for_execution(&[], owner, 0, u64::MAX, 10, 10),
            DposTransaction::UnrecognizedInput
        ));
        assert!(matches!(
            decode_dpos_transaction_for_execution(
                &[0xde, 0xad, 0xbe, 0xef],
                owner,
                0,
                u64::MAX,
                10,
                10,
            ),
            DposTransaction::UnrecognizedInput
        ));
        assert!(matches!(
            decode_dpos_transaction_for_execution(
                &DPOS_UNDELEGATE_V2_SELECTOR,
                owner,
                0,
                u64::MAX,
                10,
                10,
            ),
            DposTransaction::MethodNotSupported
        ));
        assert!(matches!(
            decode_dpos_transaction_for_execution(
                &DPOS_CLAIM_ALL_REWARDS_BATCH_SELECTOR,
                owner,
                10,
                10,
                10,
                10,
            ),
            DposTransaction::UnrecognizedInput
        ));

        let unrecognized = DposApplyOutcome::contract_failure();
        let gated =
            DposApplyOutcome::mutation_contract_failure(DposContractError::MethodNotSupported);
        assert_eq!(unrecognized.contract_error, None);
        assert_eq!(
            gated.contract_error,
            Some(DposContractError::MethodNotSupported)
        );
    }

    #[test]
    fn external_evm_pending_marker_carries_account_snapshot_status_and_decodes_legacy_marker() {
        let plan = FinalChainExternalEvmPublicationPlan {
            request_id: [0x11; 32],
            plan_id: [0x22; 32],
            period: 7,
            block_hash: [0x33; 32],
            indexed_log_bloom: FinalChainLogBloom::ZERO,
            ..Default::default()
        };
        let intent = FinalChainExternalEvmStateCommitIntent {
            request_id: plan.request_id,
            plan_id: plan.plan_id,
            period: plan.period,
            publication_block_hash: plan.block_hash,
            ..Default::default()
        };
        let post_execution_state_root = [0x44; 32];
        let post_rewards_state_root = [0x55; 32];
        let marker = external_evm_pending_publication_marker(
            plan.clone(),
            intent.clone(),
            post_execution_state_root,
            post_rewards_state_root,
        );
        assert_eq!(
            marker.account_snapshot_status,
            FINAL_CHAIN_EVM_PUBLICATION_SNAPSHOT_STATUS_UNAVAILABLE_EXTERNAL_EVM_BOUNDARY
        );

        let encoded = encode_external_evm_pending_publication_marker(&marker);
        let encoded_rlp = Rlp::new(&encoded);
        assert_eq!(encoded_rlp.item_count().unwrap(), 7);
        let decoded = decode_external_evm_pending_publication_marker(&encoded).unwrap();
        assert_eq!(
            decoded.account_snapshot_status,
            FINAL_CHAIN_EVM_PUBLICATION_SNAPSHOT_STATUS_UNAVAILABLE_EXTERNAL_EVM_BOUNDARY
        );

        let legacy_marker_id = legacy_external_evm_pending_publication_marker_id(
            &plan,
            &intent,
            post_execution_state_root,
            post_rewards_state_root,
        );
        let mut legacy_stream = RlpStream::new_list(6);
        legacy_stream.append(&EXTERNAL_EVM_PENDING_PUBLICATION_MARKER_VERSION);
        legacy_stream.append(&legacy_marker_id.as_slice());
        legacy_stream.append_raw(&encode_external_evm_publication_plan(&plan), 1);
        legacy_stream.append_raw(&encode_external_evm_state_commit_intent(&intent), 1);
        legacy_stream.append(&post_execution_state_root.as_slice());
        legacy_stream.append(&post_rewards_state_root.as_slice());
        let legacy_decoded =
            decode_external_evm_pending_publication_marker(&legacy_stream.out()).unwrap();
        assert_eq!(
            legacy_decoded.account_snapshot_status,
            FINAL_CHAIN_EVM_PUBLICATION_SNAPSHOT_STATUS_UNAVAILABLE_EXTERNAL_EVM_BOUNDARY
        );
    }

    fn header_data_rlp(gas_used: u64, total_reward: U256) -> Vec<u8> {
        let mut header_stream = RlpStream::new_list(7);
        header_stream.append(&H256::from_low_u64_be(1));
        header_stream.append(&H256::from_low_u64_be(2));
        header_stream.append(&H256::from_low_u64_be(3));
        header_stream.append(&H256::from_low_u64_be(4));
        header_stream.append(&[0u8; 256].as_slice());
        header_stream.append(&gas_used);
        header_stream.append(&total_reward);
        header_stream.out().to_vec()
    }

    fn keccak256(data: &[u8]) -> H256 {
        use tiny_keccak::{Hasher, Keccak};

        let mut hasher = Keccak::v256();
        hasher.update(data);
        let mut output = [0u8; 32];
        hasher.finalize(&mut output);
        H256::from(output)
    }

    fn append_pbft_block_fields(stream: &mut RlpStream, period: u64, timestamp: u64) {
        stream.append(&H256::from_low_u64_be(10));
        stream.append(&H256::from_low_u64_be(11));
        stream.append(&H256::from_low_u64_be(12));
        stream.append(&H256::from_low_u64_be(13));
        stream.append(&period);
        stream.append(&timestamp);
        stream.begin_list(0);
    }

    fn signed_pbft_block(signing_key: &SigningKey, period: u64, timestamp: u64) -> Vec<u8> {
        let mut unsigned_stream = RlpStream::new_list(7);
        append_pbft_block_fields(&mut unsigned_stream, period, timestamp);
        let message_hash = keccak256(&unsigned_stream.out());
        let (signature, recovery_id) = signing_key
            .sign_prehash_recoverable(message_hash.as_bytes())
            .unwrap();
        let mut signature_bytes = signature.to_bytes().to_vec();
        signature_bytes.push(recovery_id.to_byte());

        let mut signed_stream = RlpStream::new_list(8);
        append_pbft_block_fields(&mut signed_stream, period, timestamp);
        signed_stream.append(&signature_bytes);
        signed_stream.out().to_vec()
    }

    fn address_from_signing_key(signing_key: &SigningKey) -> H160 {
        let public_key = signing_key.verifying_key().to_encoded_point(false);
        let public_key_hash = keccak256(&public_key.as_bytes()[1..]);
        H160::from_slice(&public_key_hash.as_bytes()[12..])
    }

    fn register_validator_proof(
        signing_key: &SigningKey,
        validator: [u8; 20],
        recovery_id: Option<u8>,
    ) -> Vec<u8> {
        let mut message = [0u8; 32];
        {
            use tiny_keccak::{Hasher, Keccak};
            let mut hasher = Keccak::v256();
            hasher.update(&validator);
            hasher.finalize(&mut message);
        }
        let (signature, signature_recovery_id) = signing_key
            .sign_prehash_recoverable(&message)
            .expect("register validator proof signing should succeed");
        let mut proof = signature.to_bytes().to_vec();
        proof.push(
            recovery_id.unwrap_or_else(|| signature_recovery_id.to_byte().checked_add(27).unwrap()),
        );
        proof
    }

    fn register_validator_input_with_metadata_bytes(
        validator: [u8; 20],
        proof: &[u8],
        vrf_key: &[u8],
        commission: u16,
        description: &[u8],
        endpoint: &[u8],
    ) -> Vec<u8> {
        let proof_offset = 6 * 32;
        let vrf_offset = proof_offset + 32 + abi_padded_len(proof.len()).unwrap();
        let description_offset = vrf_offset + 32 + abi_padded_len(vrf_key.len()).unwrap();
        let endpoint_offset = description_offset + abi_dynamic_bytes_tail_len(description).unwrap();
        let mut input = DPOS_REGISTER_VALIDATOR_SELECTOR.to_vec();
        input.extend_from_slice(&abi_word_from_address(validator));
        input.extend_from_slice(&abi_word_from_bytes_offset(proof_offset));
        input.extend_from_slice(&abi_word_from_bytes_offset(vrf_offset));
        input.extend_from_slice(&abi_word_from_u64(u64::from(commission)));
        input.extend_from_slice(&abi_word_from_bytes_offset(description_offset));
        input.extend_from_slice(&abi_word_from_bytes_offset(endpoint_offset));
        input.extend_from_slice(&abi_word_from_usize(proof.len(), "test proof length").unwrap());
        input.extend_from_slice(proof);
        input.resize(4 + vrf_offset, 0);
        input
            .extend_from_slice(&abi_word_from_usize(vrf_key.len(), "test VRF key length").unwrap());
        input.extend_from_slice(vrf_key);
        input.resize(4 + description_offset, 0);
        input.extend_from_slice(&abi_bytes_tail(description));
        input.extend_from_slice(&abi_bytes_tail(endpoint));
        input
    }

    fn register_validator_input_with_raw_vrf(
        validator: [u8; 20],
        proof: &[u8],
        vrf_key: &[u8],
        commission: u16,
        description: &str,
        endpoint: &str,
    ) -> Vec<u8> {
        register_validator_input_with_metadata_bytes(
            validator,
            proof,
            vrf_key,
            commission,
            description.as_bytes(),
            endpoint.as_bytes(),
        )
    }

    fn period_data_rlp(pbft_block_rlp: &[u8], transaction_rlps: &[Vec<u8>]) -> Vec<u8> {
        let mut stream = RlpStream::new_list(4);
        stream.append_raw(pbft_block_rlp, 1);
        stream.begin_list(0);
        stream.begin_list(0);
        stream.begin_list(transaction_rlps.len());
        for transaction_rlp in transaction_rlps {
            stream.append_raw(transaction_rlp, 1);
        }
        stream.out().to_vec()
    }

    fn write_period_data(
        storage: &Storage,
        period: u64,
        pbft_block_rlp: &[u8],
        transaction_rlps: &[Vec<u8>],
    ) {
        let mut batch = storage.create_write_batch();
        storage
            .batch_put_raw(
                &mut batch,
                Column::PeriodData,
                &period.to_le_bytes(),
                &period_data_rlp(pbft_block_rlp, transaction_rlps),
            )
            .unwrap();
        storage.commit_write_batch_with_sync(batch, false).unwrap();
    }

