    #[test]
    fn claim_all_rewards_batch_end_output_matches_legacy_boundaries_without_reselection() {
        let is_end = |count, batch| dpos_claim_all_rewards_batch_is_end(count, batch).unwrap();
        assert!(!is_end(11, 0));
        assert!(is_end(11, 1));
        assert!(is_end(10, 0));
        assert!(is_end(11, 2));
        assert!(is_end(0, 0));
        let wrapping_batch = u32::MAX / DPOS_CLAIM_ALL_REWARDS_MAX_COUNT as u32 + 1;
        assert!(is_end(11, wrapping_batch));

        let path = temp_db_path("claim-all-batch-output-boundaries");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let final_chain = new_final_chain(storage.clone(), 200_000, 0, Vec::new(), Vec::new());
        let mut snapshot = sample_dpos_snapshot_with_undelegations();
        let mut accounts = HashMap::new();
        let delegator = [0x99; 20];
        let output = final_chain
            .apply_dpos_claim_all_rewards(&mut snapshot, &mut accounts, delegator, Some(0))
            .unwrap();
        assert_eq!(output.status_code, 1);
        assert_eq!(output.code_retval, abi_word_from_bool(true).to_vec());

        let output = final_chain
            .apply_dpos_claim_all_rewards(&mut snapshot, &mut accounts, delegator, None)
            .unwrap();
        assert_eq!(output.status_code, 1);
        assert!(output.code_retval.is_empty());

        let before_wrapping_call = snapshot.clone();
        let output = final_chain
            .apply_dpos_claim_all_rewards(
                &mut snapshot,
                &mut accounts,
                [0x11; 20],
                Some(wrapping_batch),
            )
            .unwrap();
        assert_eq!(output.status_code, 1);
        assert_eq!(output.code_retval, abi_word_from_bool(true).to_vec());
        assert_eq!(snapshot, before_wrapping_call);

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    fn encode_legacy_dpos_snapshot_without_undelegations(snapshot: &DposSnapshot) -> Vec<u8> {
        let mut stream = RlpStream::new_list(20);
        append_address_bytes_map(&mut stream, &snapshot.total_stakes);
        append_address_bytes_map(&mut stream, &snapshot.commission_rewards);
        append_validator_metadata_map(&mut stream, &snapshot.validator_metadata);
        append_address_fixed_hash_map(&mut stream, &snapshot.vrf_keys);
        append_vote_count_map(&mut stream, &snapshot.vote_counts);
        stream.append(&snapshot.total_vote_count);
        append_delegations_map(&mut stream, &snapshot.delegations);
        append_address_bytes_map(&mut stream, &snapshot.delegator_rewards);
        stream.append(&snapshot.minted_tokens.as_slice());
        stream.append(&snapshot.total_supply.as_slice());
        stream.append(&snapshot.current_yield);
        append_address_bytes_map(&mut stream, &snapshot.validator_reward_per_stake);
        append_delegations_map(&mut stream, &snapshot.delegation_reward_cursors);
        append_delegator_validators_map(&mut stream, &snapshot.delegator_validators);
        append_address_vec(&mut stream, &snapshot.validator_order);
        append_undelegations_v2_map(&mut stream, &snapshot.undelegations_v2);
        append_address_u64_map(&mut stream, &snapshot.undelegation_v2_last_ids);
        append_address_u64_map(&mut stream, &snapshot.slashing_jail_blocks);
        append_address_vec(&mut stream, &snapshot.slashing_jailed_validators);
        append_fixed_hash_set(&mut stream, &snapshot.slashing_double_voting_proofs);
        stream.out().to_vec()
    }

    fn encode_legacy_dpos_snapshot_before_delegation_ledger(
        snapshot: &DposSnapshot,
        include_vrf_keys: bool,
    ) -> Vec<u8> {
        let mut stream = RlpStream::new_list(if include_vrf_keys { 6 } else { 5 });
        append_address_bytes_map(&mut stream, &snapshot.total_stakes);
        append_address_bytes_map(&mut stream, &snapshot.commission_rewards);
        append_validator_metadata_map(&mut stream, &snapshot.validator_metadata);
        if include_vrf_keys {
            append_address_fixed_hash_map(&mut stream, &snapshot.vrf_keys);
        }
        append_vote_count_map(&mut stream, &snapshot.vote_counts);
        stream.append(&snapshot.total_vote_count);
        stream.out().to_vec()
    }

    fn encode_legacy_dpos_snapshot_with_delegation_ledger(snapshot: &DposSnapshot) -> Vec<u8> {
        let mut stream = RlpStream::new_list(7);
        append_address_bytes_map(&mut stream, &snapshot.total_stakes);
        append_address_bytes_map(&mut stream, &snapshot.commission_rewards);
        append_validator_metadata_map(&mut stream, &snapshot.validator_metadata);
        append_address_fixed_hash_map(&mut stream, &snapshot.vrf_keys);
        append_vote_count_map(&mut stream, &snapshot.vote_counts);
        stream.append(&snapshot.total_vote_count);
        append_delegations_map(&mut stream, &snapshot.delegations);
        stream.out().to_vec()
    }

    fn encode_legacy_dpos_snapshot_with_undelegations(snapshot: &DposSnapshot) -> Vec<u8> {
        let mut stream = RlpStream::new_list(21);
        append_address_bytes_map(&mut stream, &snapshot.total_stakes);
        append_address_bytes_map(&mut stream, &snapshot.commission_rewards);
        append_validator_metadata_map(&mut stream, &snapshot.validator_metadata);
        append_address_fixed_hash_map(&mut stream, &snapshot.vrf_keys);
        append_vote_count_map(&mut stream, &snapshot.vote_counts);
        stream.append(&snapshot.total_vote_count);
        append_delegations_map(&mut stream, &snapshot.delegations);
        append_address_bytes_map(&mut stream, &snapshot.delegator_rewards);
        stream.append(&snapshot.minted_tokens.as_slice());
        stream.append(&snapshot.total_supply.as_slice());
        stream.append(&snapshot.current_yield);
        append_address_bytes_map(&mut stream, &snapshot.validator_reward_per_stake);
        append_delegations_map(&mut stream, &snapshot.delegation_reward_cursors);
        append_delegator_validators_map(&mut stream, &snapshot.delegator_validators);
        append_address_vec(&mut stream, &snapshot.validator_order);
        append_undelegations_v2_map(&mut stream, &snapshot.undelegations_v2);
        append_address_u64_map(&mut stream, &snapshot.undelegation_v2_last_ids);
        append_address_u64_map(&mut stream, &snapshot.slashing_jail_blocks);
        append_address_vec(&mut stream, &snapshot.slashing_jailed_validators);
        append_fixed_hash_set(&mut stream, &snapshot.slashing_double_voting_proofs);
        append_undelegations_map(&mut stream, &snapshot.undelegations);
        stream.out().to_vec()
    }

    fn encode_legacy_dpos_snapshot_before_reward_graph(snapshot: &DposSnapshot) -> Vec<u8> {
        let current = encode_dpos_snapshot_rlp(snapshot).unwrap();
        let current = Rlp::new(&current);
        let mut stream = RlpStream::new_list(23);
        for index in 0..23 {
            stream.append_raw(current.at(index).unwrap().as_raw(), 1);
        }
        stream.out().to_vec()
    }

    fn sample_dpos_snapshot_with_undelegations() -> DposSnapshot {
        let delegator = [0x11u8; 20];
        let validator = [0x22u8; 20];
        let mut total_stakes = BTreeMap::new();
        total_stakes.insert(validator, u256_to_big_endian(U256::from(10_000u64)));
        let mut commission_rewards = BTreeMap::new();
        commission_rewards.insert(validator, u256_to_big_endian(U256::from(250u64)));
        let mut validator_metadata = BTreeMap::new();
        validator_metadata.insert(
            validator,
            DposValidatorMetadata {
                owner: [0x33u8; 20],
                commission: 1234,
                description: b"validator".to_vec(),
                endpoint: b"endpoint".to_vec(),
                last_commission_change: 12,
            },
        );
        let mut vote_counts = BTreeMap::new();
        vote_counts.insert(validator, 7);
        let mut delegations = BTreeMap::new();
        let mut delegator_map = BTreeMap::new();
        delegator_map.insert(delegator, u256_to_big_endian(U256::from(10_000u64)));
        delegations.insert(validator, delegator_map);
        let mut delegator_rewards = BTreeMap::new();
        delegator_rewards.insert(validator, u256_to_big_endian(U256::from(15u64)));
        let mut delegation_reward_cursors = BTreeMap::new();
        let mut delegator_cursor_map = BTreeMap::new();
        delegator_cursor_map.insert(delegator, u256_to_big_endian(U256::from(2u64)));
        delegation_reward_cursors.insert(validator, delegator_cursor_map);
        let mut validator_reward_per_stake = BTreeMap::new();
        validator_reward_per_stake.insert(validator, u256_to_big_endian(U256::from(30_000u64)));

        let mut undelegations_v2 = BTreeMap::new();
        undelegations_v2.insert(
            delegator,
            vec![DposValidatorUndelegationsV2 {
                validator,
                entries: vec![DposUndelegationV2Entry {
                    id: 1,
                    amount: u256_to_big_endian(U256::from(2_000u64)),
                    block: 50,
                }],
            }],
        );
        let mut undelegations = BTreeMap::new();
        undelegations.insert(
            delegator,
            vec![DposUndelegation {
                validator,
                amount: u256_to_big_endian(U256::from(3_000u64)),
                block: 5,
            }],
        );
        let mut undelegation_v2_last_ids = BTreeMap::new();
        undelegation_v2_last_ids.insert(delegator, 1);
        let mut slashing_jail_blocks = BTreeMap::new();
        slashing_jail_blocks.insert(validator, 99);
        let mut slashing_double_voting_proofs = BTreeSet::new();
        slashing_double_voting_proofs.insert([0x99u8; 32]);
        let mut delegator_validators = BTreeMap::new();
        delegator_validators.insert(delegator, vec![validator]);
        let mut validator_order = Vec::new();
        validator_order.push(validator);
        let mut vrf_keys = BTreeMap::new();
        vrf_keys.insert(validator, [0x55u8; 32]);
        let mut reward_reference_graph = DposRewardGraph::new();
        reward_reference_graph
            .bootstrap_node(
                NodeKey {
                    validator,
                    block: 0,
                },
                Node {
                    reward_per_stake: BigUint::from(2_u8),
                    count: 1,
                },
                false,
                &[delegator],
            )
            .unwrap();
        reward_reference_graph.next_block(1).unwrap();
        reward_reference_graph
            .bootstrap_node(
                NodeKey {
                    validator,
                    block: 1,
                },
                Node {
                    reward_per_stake: BigUint::from(30_000_u64),
                    count: 1,
                },
                true,
                &[],
            )
            .unwrap();

        DposSnapshot {
            total_stakes,
            commission_rewards,
            delegator_rewards,
            validator_metadata,
            vrf_keys,
            vote_counts,
            total_vote_count: 7,
            delegations,
            validator_order,
            delegator_validators,
            delegation_ledger_history_complete: true,
            delegation_reward_cursors,
            validator_reward_per_stake,
            minted_tokens: vec![0x11, 0x22, 0x33],
            total_supply: vec![0x33, 0x44, 0x55],
            current_yield: 100,
            undelegations_v2,
            undelegations,
            undelegation_v2_last_ids,
            slashing_jail_blocks,
            slashing_jailed_validators: vec![validator],
            slashing_double_voting_proofs,
            redelegate_same_validator_history_complete: true,
            redelegate_same_validator_corruption: BTreeSet::new(),
            reward_reference_graph,
        }
    }

    #[test]
    fn total_delegation_restart_guard_distinguishes_principal_ledger_schemas() {
        let snapshot = sample_dpos_snapshot_with_undelegations();
        let delegator = [0x11; 20];

        for include_vrf_keys in [false, true] {
            let legacy =
                encode_legacy_dpos_snapshot_before_delegation_ledger(&snapshot, include_vrf_keys);
            let decoded = decode_dpos_snapshot_rlp(&legacy).unwrap();
            assert!(!decoded.delegation_ledger_history_complete);
            assert!(
                FinalChain::encode_dpos_total_delegation_from_snapshot(&decoded, delegator)
                    .unwrap_err()
                    .to_string()
                    .contains("delegation ledger is incomplete")
            );
            let restarted =
                decode_dpos_snapshot_rlp(&encode_dpos_snapshot_rlp(&decoded).unwrap()).unwrap();
            assert!(
                !restarted.delegation_ledger_history_complete,
                "the schema-five/six rebuild requirement must survive re-encoding"
            );
        }

        let schema_seven = decode_dpos_snapshot_rlp(
            &encode_legacy_dpos_snapshot_with_delegation_ledger(&snapshot),
        )
        .unwrap();
        assert!(schema_seven.delegation_ledger_history_complete);
        assert_eq!(
            u256_from_big_endian(
                &FinalChain::encode_dpos_total_delegation_from_snapshot(&schema_seven, delegator,)
                    .unwrap()
            ),
            U256::from(10_000u64)
        );
        let restarted_schema_seven =
            decode_dpos_snapshot_rlp(&encode_dpos_snapshot_rlp(&schema_seven).unwrap()).unwrap();
        assert!(restarted_schema_seven.delegation_ledger_history_complete);

        let current =
            decode_dpos_snapshot_rlp(&encode_dpos_snapshot_rlp(&snapshot).unwrap()).unwrap();
        assert!(current.delegation_ledger_history_complete);
        assert_eq!(current, snapshot);
    }

    #[test]
    fn total_delegation_uses_authoritative_membership_for_direct_value_gas_and_corruption() {
        let path = temp_db_path("total-delegation-direct-semantics");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let final_chain = new_final_chain_with_dpos(
            storage.clone(),
            vec![],
            U256::zero(),
            U256::from(1_000u64),
            U256::from(30_000u64),
        );
        let delegator = [0x11; 20];
        let first_validator = [0x22; 20];
        let second_validator = [0x44; 20];
        let mut snapshot = sample_dpos_snapshot_with_undelegations();
        snapshot.delegations.insert(
            second_validator,
            BTreeMap::from([(delegator, u256_to_big_endian(U256::from(7_000u64)))]),
        );
        snapshot
            .delegator_validators
            .insert(delegator, vec![second_validator, first_validator]);
        final_chain
            .insert_dpos_snapshot(0, snapshot.clone())
            .unwrap();

        let input = get_total_delegation_input(delegator);
        let direct = final_chain
            .call(dpos_call_request(0, input.clone()))
            .unwrap();
        assert_eq!(direct.gas_used, 2 * DPOS_BATCH_GET_REWARDS_GAS);
        assert_eq!(
            u256_from_big_endian(&direct.code_retval),
            U256::from(17_000u64)
        );
        let empty = final_chain
            .call(dpos_call_request(0, get_total_delegation_input([0xff; 20])))
            .unwrap();
        assert_eq!(empty.gas_used, 0);
        assert_eq!(u256_from_big_endian(&empty.code_retval), U256::zero());

        let mut high_address_and_trailing = input;
        high_address_and_trailing[4..16].fill(0xff);
        high_address_and_trailing.extend_from_slice(&[0xaa, 0xbb]);
        let permissive = final_chain
            .call(dpos_call_request(0, high_address_and_trailing))
            .unwrap();
        assert_eq!(permissive.code_retval, direct.code_retval);
        assert_eq!(permissive.gas_used, direct.gas_used);

        let malformed = final_chain
            .call(dpos_call_request(
                0,
                DPOS_GET_TOTAL_DELEGATION_SELECTOR.to_vec(),
            ))
            .unwrap();
        assert_eq!(malformed.gas_used, 0);
        assert!(!malformed.code_err.is_empty());

        let mut duplicate = snapshot.clone();
        duplicate
            .delegator_validators
            .get_mut(&delegator)
            .unwrap()
            .push(second_validator);
        assert!(
            FinalChain::encode_dpos_total_delegation_from_snapshot(&duplicate, delegator)
                .unwrap_err()
                .to_string()
                .contains("duplicate validator")
        );
        let mut dangling = snapshot.clone();
        dangling
            .delegations
            .get_mut(&second_validator)
            .unwrap()
            .remove(&delegator);
        assert!(
            dpos_total_delegation_storage_read_count(&dangling, delegator)
                .unwrap_err()
                .to_string()
                .contains("missing principal row")
        );
        let mut over_wide = snapshot.clone();
        over_wide
            .delegations
            .get_mut(&second_validator)
            .unwrap()
            .insert(delegator, vec![1; 33]);
        assert!(
            dpos_total_delegation_storage_read_count(&over_wide, delegator)
                .unwrap_err()
                .to_string()
                .contains("exceeds uint256")
        );
        let mut overflow = snapshot;
        overflow
            .delegations
            .get_mut(&first_validator)
            .unwrap()
            .insert(delegator, u256_to_big_endian(U256::MAX));
        overflow
            .delegations
            .get_mut(&second_validator)
            .unwrap()
            .insert(delegator, vec![1]);
        assert!(
            FinalChain::encode_dpos_total_delegation_from_snapshot(&overflow, delegator)
                .unwrap_err()
                .to_string()
                .contains("total delegation overflow")
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn delegation_pages_preserve_graph_rewards_order_wrapping_gas_and_corruption_rules() {
        let path = temp_db_path("delegation-page-graph-semantics");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let delegator = [0xa1; 20];
        let expected_order = (1u8..=21)
            .rev()
            .map(|index| [index; 20])
            .collect::<Vec<_>>();
        let validators = expected_order
            .iter()
            .map(|validator| {
                let mut genesis = genesis_validator(*validator, U256::from(10_000u64));
                genesis.delegations = vec![(delegator, u256_to_big_endian(U256::from(10_000u64)))];
                genesis
            })
            .collect::<Vec<_>>();
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            1_000_000,
            0,
            vec![genesis_account(delegator, U256::from(1_000_000u64))],
            validators,
            GenesisDposConfig {
                eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
                vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
                validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
                ..Default::default()
            },
            FinalChainRewardsConfig {
                cornus_period: 1,
                ..Default::default()
            },
        )
        .unwrap();

        let page_zero_input = get_delegations_input(delegator, 0);
        let page_zero = final_chain
            .call(dpos_call_request(0, page_zero_input.clone()))
            .unwrap();
        let (entries, is_end) = delegation_page_entries(&page_zero.code_retval);
        assert_eq!(page_zero.gas_used, 100_000);
        assert!(!is_end);
        assert_eq!(
            entries
                .iter()
                .map(|(validator, _, _)| *validator)
                .collect::<Vec<_>>(),
            expected_order[..20]
        );
        assert!(
            entries
                .iter()
                .all(|(_, stake, reward)| *stake == U256::from(10_000u64) && reward.is_zero())
        );

        let page_one = final_chain
            .call(dpos_call_request(0, get_delegations_input(delegator, 1)))
            .unwrap();
        assert_eq!(page_one.gas_used, 5_000);
        assert_eq!(
            delegation_page_entries(&page_one.code_retval),
            (
                vec![(expected_order[20], U256::from(10_000u64), U256::zero())],
                true
            )
        );
        let out_of_range = final_chain
            .call(dpos_call_request(0, get_delegations_input(delegator, 2)))
            .unwrap();
        assert_eq!(out_of_range.gas_used, 5_000);
        assert_eq!(
            delegation_page_entries(&out_of_range.code_retval),
            (vec![], true)
        );

        let high_batch = final_chain
            .call(dpos_call_request(
                0,
                get_delegations_input(delegator, 0x8000_0000),
            ))
            .unwrap();
        assert_eq!(high_batch.gas_used, 5_000);
        assert_eq!(high_batch.code_retval, page_zero.code_retval);

        let mut permissive = page_zero_input.clone();
        permissive[4] = 0xaa;
        permissive[36..64].fill(0xff);
        permissive[64..68].fill(0);
        permissive.extend_from_slice(&[0xbb, 0xcc]);
        assert_eq!(
            final_chain
                .call(dpos_call_request(0, permissive))
                .unwrap()
                .code_retval,
            page_zero.code_retval
        );
        let malformed = final_chain
            .call(dpos_call_request(0, DPOS_GET_DELEGATIONS_SELECTOR.to_vec()))
            .unwrap();
        assert_eq!(malformed.gas_used, 0);
        assert!(!malformed.code_err.is_empty());
        assert!(malformed.code_retval.is_empty());
        let mut pre_cornus_value = dpos_call_request(0, page_zero_input.clone());
        pre_cornus_value.value = U256::one().into();
        assert!(
            final_chain
                .call(pre_cornus_value)
                .unwrap()
                .code_err
                .is_empty()
        );
        let mut cornus_value = dpos_call_request(1, page_zero_input.clone());
        cornus_value.value = U256::one().into();
        let cornus_value = final_chain.call(cornus_value).unwrap();
        assert_eq!(cornus_value.gas_used, 0);
        assert_eq!(cornus_value.code_err, "DPoS method is not payable");

        let native_read_input = page_zero_input.clone();
        let native = final_chain
            .execute_native_transactions(
                1,
                &[
                    test_transaction(
                        0x8f,
                        delegator,
                        Some(DPOS_CONTRACT_ADDRESS),
                        0,
                        U256::zero(),
                        U256::zero(),
                        200_000,
                        undelegate_input(expected_order[0], U256::from(10_000u64)),
                        vec![0xc1, 0x8f],
                    ),
                    test_transaction(
                        0x90,
                        delegator,
                        Some(DPOS_CONTRACT_ADDRESS),
                        1,
                        U256::zero(),
                        U256::zero(),
                        200_000,
                        undelegate_input(expected_order[1], U256::from(10_000u64)),
                        vec![0xc1, 0x90],
                    ),
                    test_transaction(
                        0x91,
                        delegator,
                        Some(DPOS_CONTRACT_ADDRESS),
                        2,
                        U256::zero(),
                        U256::zero(),
                        200_000,
                        native_read_input.clone(),
                        vec![0xc1, 0x91],
                    ),
                ],
            )
            .unwrap();
        assert_eq!(
            native
                .receipts
                .iter()
                .map(|receipt| receipt.status_code)
                .collect::<Vec<_>>(),
            vec![1, 1, 1]
        );
        assert_eq!(
            native.receipts[2].gas_used,
            intrinsic_gas(&native_read_input, false).unwrap() + 95_000
        );

        let first_validator = expected_order[0];
        let mut reward_snapshot = final_chain.dpos_snapshot(0).unwrap();
        reward_snapshot
            .delegator_rewards
            .insert(first_validator, u256_to_big_endian(U256::from(100u64)));
        let reward_page = final_chain
            .encode_dpos_delegations_from_snapshot(&reward_snapshot, delegator, 0)
            .unwrap();
        assert_eq!(
            delegation_page_entries(&reward_page).0[0].2,
            U256::from(100u64)
        );

        let mut zero_stake = reward_snapshot.clone();
        zero_stake.reward_reference_graph.next_block(1).unwrap();
        zero_stake
            .reward_reference_graph
            .bootstrap_node(
                NodeKey {
                    validator: first_validator,
                    block: 1,
                },
                Node {
                    reward_per_stake: BigUint::from(300_u64),
                    count: 1,
                },
                true,
                &[],
            )
            .unwrap();
        zero_stake
            .total_stakes
            .insert(first_validator, u256_to_big_endian(U256::zero()));
        zero_stake.delegator_rewards.remove(&first_validator);
        let zero_page = final_chain
            .encode_dpos_delegations_from_snapshot(&zero_stake, delegator, 0)
            .unwrap();
        assert_eq!(delegation_page_entries(&zero_page).0[0].2, U256::zero());

        let mut duplicate = reward_snapshot.clone();
        duplicate
            .delegator_validators
            .get_mut(&delegator)
            .unwrap()
            .push(first_validator);
        assert!(
            final_chain
                .encode_dpos_delegations_from_snapshot(&duplicate, delegator, 0)
                .unwrap_err()
                .to_string()
                .contains("duplicate validator")
        );
        let mut missing_principal = reward_snapshot.clone();
        missing_principal
            .delegations
            .get_mut(&first_validator)
            .unwrap()
            .remove(&delegator);
        assert!(
            final_chain
                .encode_dpos_delegations_from_snapshot(&missing_principal, delegator, 0)
                .unwrap_err()
                .to_string()
                .contains("missing principal")
        );
        let mut missing_validator = reward_snapshot.clone();
        missing_validator.total_stakes.remove(&first_validator);
        assert!(
            final_chain
                .encode_dpos_delegations_from_snapshot(&missing_validator, delegator, 0)
                .unwrap_err()
                .to_string()
                .contains("missing validator row")
        );
        let mut missing_cursor = reward_snapshot.clone();
        missing_cursor
            .reward_reference_graph
            .delete_cursor(&first_validator, &delegator)
            .unwrap();
        assert!(
            final_chain
                .encode_dpos_delegations_from_snapshot(&missing_cursor, delegator, 0)
                .unwrap_err()
                .to_string()
                .contains("missing cursor")
        );
        let mut incomplete = reward_snapshot;
        incomplete.reward_reference_graph = DposRewardGraph::incomplete();
        for (page_delegator, batch) in [(delegator, 0), (delegator, 2), ([0xff; 20], 0)] {
            assert!(
                final_chain
                    .encode_dpos_delegations_from_snapshot(&incomplete, page_delegator, batch)
                    .unwrap_err()
                    .to_string()
                    .contains("graph history is incomplete")
            );
        }

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn decode_dpos_snapshot_rlp_preserves_new_undelegation_item() {
        let snapshot = sample_dpos_snapshot_with_undelegations();
        let encoded_snapshot = encode_dpos_snapshot_rlp(&snapshot).unwrap();
        let decoded_snapshot = decode_dpos_snapshot_rlp(&encoded_snapshot).unwrap();
        assert_eq!(decoded_snapshot, snapshot);

        let legacy_snapshot = encode_legacy_dpos_snapshot_without_undelegations(&snapshot);
        let decoded_legacy_snapshot = decode_dpos_snapshot_rlp(&legacy_snapshot).unwrap();
        let mut expected_legacy_snapshot = snapshot;
        expected_legacy_snapshot.undelegations = BTreeMap::new();
        expected_legacy_snapshot.redelegate_same_validator_history_complete = false;
        expected_legacy_snapshot.reward_reference_graph = DposRewardGraph::incomplete();
        assert_eq!(decoded_legacy_snapshot, expected_legacy_snapshot);
    }

