    #[test]
    fn same_block_registration_replaces_terminal_deletion_orphan_node() {
        let path = temp_db_path("dpos-same-block-delete-reregister-graph-orphan");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator_key = SigningKey::from_slice(&[0x47_u8; 32]).unwrap();
        let validator: [u8; 20] = address_from_signing_key(&validator_key).into();
        let final_chain = new_final_chain_with_dpos(
            storage,
            vec![genesis_validator(validator, U256::from(10_000u64))],
            U256::zero(),
            U256::from(1_000u64),
            U256::from(30_000u64),
        );
        let mut snapshot = final_chain.dpos_snapshot_at_finalized_block(0).unwrap();
        let head = snapshot
            .reward_reference_graph
            .read_validator_head(&validator)
            .unwrap();
        snapshot
            .reward_reference_graph
            .write_cursor(validator, validator, head)
            .unwrap();
        snapshot
            .reward_reference_graph
            .delete_cursor(&validator, &validator)
            .unwrap();
        snapshot.delegations.remove(&validator);
        snapshot.delegation_reward_cursors.remove(&validator);
        remove_delegator_validator(&mut snapshot.delegator_validators, validator, validator);
        snapshot
            .total_stakes
            .insert(validator, u256_to_big_endian(U256::zero()));
        snapshot
            .commission_rewards
            .insert(validator, u256_to_big_endian(U256::zero()));
        snapshot.vote_counts.insert(validator, 0);
        snapshot.total_vote_count = 0;

        remove_dpos_validator(&mut snapshot, validator, false).unwrap();
        let orphan_key = NodeKey {
            validator,
            block: head,
        };
        assert_eq!(
            snapshot
                .reward_reference_graph
                .load_node(&orphan_key)
                .unwrap()
                .count,
            1
        );

        let input = register_validator_input(
            validator,
            &register_validator_proof(&validator_key, validator, None),
            [0x47; 32],
            0,
            "registered again",
            "same block",
        );
        let mut registration = decode_dpos_register_validator(&input, validator).unwrap();
        registration.stake = u256_to_big_endian(U256::from(10_000u64));
        let outcome = final_chain
            .apply_dpos_registration(&mut snapshot, registration, head)
            .unwrap();

        assert_eq!(outcome.status_code, 1);
        assert_eq!(
            snapshot
                .reward_reference_graph
                .load_node(&orphan_key)
                .unwrap(),
            Node {
                reward_per_stake: BigUint::from(0_u8),
                count: 2,
            }
        );
        assert_eq!(
            snapshot
                .reward_reference_graph
                .read_validator_head(&validator)
                .unwrap(),
            head
        );
        assert_eq!(
            snapshot
                .reward_reference_graph
                .read_cursor(&validator, &validator)
                .unwrap(),
            head
        );

        drop(final_chain);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn v1_undelegation_helpers_preserve_zero_order_paging_and_mixed_counts() {
        let delegator = [0x41; 20];
        let query_snapshot = sample_dpos_snapshot_with_undelegations();
        let query_validator = [0x22; 20];
        let path = temp_db_path("v1-undelegation-magnolia-count-boundary");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            0,
            0,
            vec![],
            vec![],
            GenesisDposConfig::default(),
            FinalChainRewardsConfig {
                magnolia_period: 10,
                ..Default::default()
            },
        )
        .unwrap();
        let pre_magnolia = final_chain
            .encode_dpos_validator_basic_info_payload(&query_snapshot, query_validator, 9)
            .unwrap();
        let post_magnolia = final_chain
            .encode_dpos_validator_basic_info_payload(&query_snapshot, query_validator, 10)
            .unwrap();
        assert_eq!(u256_from_big_endian(&pre_magnolia[128..160]), U256::zero());
        assert_eq!(
            u256_from_big_endian(&post_magnolia[128..160]),
            U256::from(2u64)
        );

        let mut snapshot = query_snapshot;
        snapshot.undelegations.clear();
        snapshot.undelegations_v2.clear();

        for index in 1u8..=21 {
            create_undelegation(
                &mut snapshot,
                delegator,
                [index; 20],
                u256_to_big_endian(if index == 1 {
                    U256::zero()
                } else {
                    U256::from(index)
                }),
                u64::from(index),
            )
            .unwrap();
        }

        let ordered = dpos_undelegations_for_delegator(&snapshot, delegator);
        assert_eq!(ordered.len(), 21);
        assert_eq!(ordered[0].validator, [1; 20]);
        assert_eq!(u256_from_big_endian(&ordered[0].amount), U256::zero());
        assert_eq!(ordered[20].validator, [21; 20]);
        assert_eq!(
            dpos_undelegations_storage_read_count(&snapshot, delegator, 0).unwrap(),
            20
        );
        assert_eq!(
            dpos_undelegations_storage_read_count(&snapshot, delegator, 1).unwrap(),
            1
        );
        assert_eq!(
            dpos_undelegations_storage_read_count(&snapshot, delegator, 2).unwrap(),
            1
        );

        snapshot.undelegations_v2.insert(
            delegator,
            vec![DposValidatorUndelegationsV2 {
                validator: [1; 20],
                entries: vec![DposUndelegationV2Entry {
                    id: 1,
                    amount: u256_to_big_endian(U256::from(7u64)),
                    block: 30,
                }],
            }],
        );
        assert_eq!(
            dpos_undelegations_count_for_validator(&snapshot, [1; 20]),
            2
        );

        let removed = remove_undelegation(&mut snapshot, delegator, [1; 20]).unwrap();
        assert_eq!(u256_from_big_endian(&removed.amount), U256::zero());
        assert_eq!(
            dpos_undelegations_for_delegator(&snapshot, delegator)[0].validator,
            [21; 20]
        );
        assert_eq!(
            dpos_undelegations_count_for_validator(&snapshot, [1; 20]),
            1
        );
        snapshot
            .total_stakes
            .insert([1; 20], u256_to_big_endian(U256::zero()));
        snapshot
            .commission_rewards
            .insert([1; 20], u256_to_big_endian(U256::zero()));
        snapshot.vote_counts.insert([1; 20], 0);
        assert!(snapshot.total_stakes.contains_key(&[1; 20]));

        assert!(remove_undelegation_v2(&mut snapshot, delegator, [1; 20], 1));
        assert_eq!(
            dpos_undelegations_count_for_validator(&snapshot, [1; 20]),
            0
        );
        snapshot
            .redelegate_same_validator_corruption
            .insert([1; 20]);
        let corrupt_before = snapshot.clone();
        assert!(
            remove_dpos_validator(&mut snapshot, [1; 20], false)
                .unwrap_err()
                .to_string()
                .contains("missing validator head")
        );
        assert_eq!(snapshot, corrupt_before);
        let graph_block = snapshot.reward_reference_graph.current_block().unwrap();
        snapshot
            .reward_reference_graph
            .bootstrap_node(
                NodeKey {
                    validator: [1; 20],
                    block: graph_block,
                },
                Node {
                    reward_per_stake: BigUint::from(0_u8),
                    count: 1,
                },
                true,
                &[],
            )
            .unwrap();
        remove_dpos_validator(&mut snapshot, [1; 20], false).unwrap();
        assert!(!snapshot.total_stakes.contains_key(&[1; 20]));
        assert!(
            !snapshot
                .redelegate_same_validator_corruption
                .contains(&[1; 20])
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

