    #[test]
    fn validator_page_calls_preserve_legacy_paging_decode_and_corruption_rules() {
        let path = temp_db_path("validator-page-call-parity");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let first_owner = [0xa1; 20];
        let second_owner = [0xa2; 20];
        let validators = (1u8..=22)
            .map(|index| {
                let owner = if index % 2 == 0 {
                    first_owner
                } else {
                    second_owner
                };
                genesis_validator_with_metadata(
                    [index; 20],
                    U256::from(10_000u64),
                    owner,
                    u16::from(index),
                    &format!("validator {index}"),
                    &format!("endpoint {index}"),
                )
            })
            .collect::<Vec<_>>();
        let dpos_config = GenesisDposConfig {
            eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
            vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
            validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
            ..Default::default()
        };
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            1_000_000,
            0,
            vec![],
            validators.clone(),
            dpos_config.clone(),
            FinalChainRewardsConfig {
                cornus_period: 1,
                ..Default::default()
            },
        )
        .unwrap();

        let first_page = final_chain
            .call(dpos_call_request(0, get_validators_input(0)))
            .unwrap();
        assert_eq!(first_page.gas_used, 100_000);
        assert_eq!(
            u256_from_big_endian(&first_page.code_retval[96..128]),
            U256::from(640u64),
            "the first tuple offset is relative to the element-head start"
        );
        let first_payload_start = 96usize + 640;
        assert_eq!(
            &first_page.code_retval[first_payload_start + 12..first_payload_start + 32],
            &[1; 20],
            "raw legacy ABI bytes must locate the first validator independently of the decoder"
        );
        assert_eq!(
            validator_page_addresses(&first_page.code_retval),
            ((1u8..=20).map(|index| [index; 20]).collect(), false)
        );
        let partial_page = final_chain
            .call(dpos_call_request(0, get_validators_input(1)))
            .unwrap();
        assert_eq!(partial_page.gas_used, 10_000);
        assert_eq!(
            u256_from_big_endian(&partial_page.code_retval[96..128]),
            U256::from(64u64)
        );
        assert_eq!(
            validator_page_addresses(&partial_page.code_retval),
            (vec![[21; 20], [22; 20]], true)
        );
        let out_of_range = final_chain
            .call(dpos_call_request(0, get_validators_input(2)))
            .unwrap();
        assert_eq!(out_of_range.gas_used, 5_000);
        assert_eq!(
            validator_page_addresses(&out_of_range.code_retval),
            (vec![], true)
        );

        let owner_page = final_chain
            .call(dpos_call_request(
                0,
                get_validators_for_input(first_owner, 0),
            ))
            .unwrap();
        assert_eq!(owner_page.gas_used, 100_000);
        assert_eq!(
            validator_page_addresses(&owner_page.code_retval),
            (
                (2u8..=22).step_by(2).map(|index| [index; 20]).collect(),
                true,
            )
        );
        let empty_owner_page = final_chain
            .call(dpos_call_request(
                0,
                get_validators_for_input([0xff; 20], 0),
            ))
            .unwrap();
        assert_eq!(empty_owner_page.gas_used, 100_000);
        assert_eq!(
            validator_page_addresses(&empty_owner_page.code_retval),
            (vec![], true)
        );

        let overflow_batch = 0xcccc_cccdu32;
        let mut overflow_input = get_validators_input(overflow_batch);
        overflow_input[4] = 0x77;
        overflow_input.extend_from_slice(&[0xee; 17]);
        let overflow_page = final_chain
            .call(dpos_call_request(0, overflow_input))
            .unwrap();
        assert_eq!(overflow_page.gas_used, 5_000);
        assert_eq!(
            validator_page_addresses(&overflow_page.code_retval),
            ((5u8..=22).map(|index| [index; 20]).collect(), true)
        );
        let mut overflow_owner_input = get_validators_for_input(first_owner, overflow_batch);
        overflow_owner_input[4] = 0x66;
        overflow_owner_input[36] = 0x55;
        overflow_owner_input.extend_from_slice(&[0xdd; 9]);
        let overflow_owner_page = final_chain
            .call(dpos_call_request(0, overflow_owner_input))
            .unwrap();
        assert_eq!(overflow_owner_page.gas_used, 100_000);
        assert_eq!(
            validator_page_addresses(&overflow_owner_page.code_retval),
            (
                (10u8..=22).step_by(2).map(|index| [index; 20]).collect(),
                true,
            )
        );

        let malformed = final_chain
            .call(dpos_call_request(0, DPOS_GET_VALIDATORS_SELECTOR.to_vec()))
            .unwrap();
        assert_eq!(malformed.gas_used, 0);
        assert!(!malformed.code_err.is_empty());
        let malformed_for = final_chain
            .call(dpos_call_request(
                0,
                DPOS_GET_VALIDATORS_FOR_SELECTOR.to_vec(),
            ))
            .unwrap();
        assert_eq!(malformed_for.gas_used, 0);
        assert!(!malformed_for.code_err.is_empty());
        let mut pre_cornus_value = dpos_call_request(0, get_validators_input(0));
        pre_cornus_value.value = U256::one().into();
        assert_eq!(final_chain.call(pre_cornus_value).unwrap().code_err, "");

        let mut snapshot = final_chain.dpos_snapshot(0).unwrap();
        let mut empty_snapshot = snapshot.clone();
        empty_snapshot.validator_order.clear();
        let empty_page = final_chain
            .encode_dpos_validators_from_snapshot(&empty_snapshot, 0, 0)
            .unwrap();
        assert_eq!(
            validator_page_addresses(&empty_page),
            (Vec::<[u8; 20]>::new(), true)
        );
        assert_eq!(
            dpos_transaction_required_gas(
                &DposTransaction::GetValidators(Ok(0)),
                0,
                u64::MAX,
                1,
                Some(&empty_snapshot),
            )
            .unwrap(),
            DPOS_BATCH_GET_REWARDS_GAS
        );
        snapshot
            .total_stakes
            .insert([2; 20], u256_to_big_endian(U256::zero()));
        snapshot
            .commission_rewards
            .insert([2; 20], u256_to_big_endian(U256::zero()));
        let delegators = snapshot
            .delegations
            .remove(&[2; 20])
            .unwrap_or_default()
            .into_keys()
            .collect::<Vec<_>>();
        for delegator in delegators {
            remove_delegator_validator(&mut snapshot.delegator_validators, delegator, [2; 20]);
            snapshot
                .reward_reference_graph
                .delete_cursor(&[2; 20], &delegator)
                .unwrap();
        }
        snapshot.delegation_reward_cursors.remove(&[2; 20]);
        remove_dpos_validator(&mut snapshot, [2; 20], false).unwrap();
        assert_eq!(snapshot.validator_order[1], [22; 20]);
        assert_eq!(snapshot.validator_order.len(), 21);
        let swapped_page = final_chain
            .encode_dpos_validators_from_snapshot(&snapshot, 0, 0)
            .unwrap();
        assert_eq!(validator_page_addresses(&swapped_page).0[1], [22; 20]);
        let restarted_snapshot =
            decode_dpos_snapshot_rlp(&encode_dpos_snapshot_rlp(&snapshot).unwrap()).unwrap();
        let restarted_page = final_chain
            .encode_dpos_validators_from_snapshot(&restarted_snapshot, 0, 0)
            .unwrap();
        assert_eq!(restarted_page, swapped_page);

        let mut corrupt_snapshot = restarted_snapshot;
        corrupt_snapshot.validator_metadata.remove(&[1; 20]);
        let corruption = final_chain
            .encode_dpos_validators_from_snapshot(&corrupt_snapshot, 0, 0)
            .unwrap_err();
        assert!(corruption.to_string().contains("missing metadata"));

        let cornus_path = temp_db_path("validator-page-call-cornus");
        let cornus_storage = Arc::new(Storage::new(Config::new(cornus_path.clone())).unwrap());
        let cornus_chain = FinalChain::new_with_rewards_config(
            cornus_storage.clone(),
            1_000_000,
            0,
            vec![],
            validators,
            dpos_config,
            FinalChainRewardsConfig {
                cornus_period: 0,
                ..Default::default()
            },
        )
        .unwrap();
        let mut nonpayable = dpos_call_request(0, DPOS_GET_VALIDATORS_FOR_SELECTOR.to_vec());
        nonpayable.value = U256::one().into();
        let nonpayable = cornus_chain.call(nonpayable).unwrap();
        assert_eq!(nonpayable.gas_used, 0);
        assert_eq!(nonpayable.code_err, "DPoS method is not payable");

        drop(final_chain);
        drop(storage);
        drop(cornus_chain);
        drop(cornus_storage);
        let _ = std::fs::remove_dir_all(path);
        let _ = std::fs::remove_dir_all(cornus_path);
    }

    #[test]
    fn call_reads_genesis_dpos_precompile_methods() {
        let path = temp_db_path("call-genesis-dpos");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator = [0x10; 20];
        let final_chain = new_final_chain_with_dpos(
            storage.clone(),
            vec![genesis_validator(validator, U256::from(10_000u64))],
            U256::from(1_000u64),
            U256::from(1_000u64),
            U256::from(30_000u64),
        );

        let total_votes = final_chain
            .call(dpos_call_request(
                0,
                DPOS_GET_TOTAL_ELIGIBLE_VOTES_SELECTOR.to_vec(),
            ))
            .unwrap();
        assert_eq!(total_votes.code_err, "");
        assert_eq!(total_votes.gas_used, DPOS_DEFAULT_METHOD_GAS);
        assert_eq!(
            u256_from_big_endian(&total_votes.code_retval),
            U256::from(10u64)
        );

        let eligible = final_chain
            .call(dpos_call_request(
                0,
                dpos_eligibility_address_input(DPOS_IS_VALIDATOR_ELIGIBLE_SELECTOR, validator),
            ))
            .unwrap();
        assert_eq!(eligible.code_err, "");
        assert_eq!(eligible.gas_used, DPOS_DEFAULT_METHOD_GAS);
        assert_eq!(u256_from_big_endian(&eligible.code_retval), U256::one());

        let validator_votes = final_chain
            .call(dpos_call_request(
                0,
                dpos_eligibility_address_input(
                    DPOS_GET_VALIDATOR_ELIGIBLE_VOTES_SELECTOR,
                    validator,
                ),
            ))
            .unwrap();
        assert_eq!(validator_votes.code_err, "");
        assert_eq!(validator_votes.gas_used, DPOS_DEFAULT_METHOD_GAS);
        assert_eq!(
            u256_from_big_endian(&validator_votes.code_retval),
            U256::from(10u64)
        );

        let missing_eligible = final_chain
            .call(dpos_call_request(
                0,
                dpos_eligibility_address_input(DPOS_IS_VALIDATOR_ELIGIBLE_SELECTOR, [0x99; 20]),
            ))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&missing_eligible.code_retval),
            U256::zero()
        );

        let mut trailing_input =
            dpos_eligibility_address_input(DPOS_GET_VALIDATOR_ELIGIBLE_VOTES_SELECTOR, validator);
        trailing_input.extend_from_slice(&[0xaa; 32]);
        let trailing = final_chain
            .call(dpos_call_request(0, trailing_input))
            .unwrap();
        assert_eq!(trailing.code_err, "");
        assert_eq!(
            u256_from_big_endian(&trailing.code_retval),
            U256::from(10u64)
        );

        let malformed = final_chain
            .call(dpos_call_request(
                0,
                DPOS_IS_VALIDATOR_ELIGIBLE_SELECTOR.to_vec(),
            ))
            .unwrap();
        assert!(!malformed.code_err.is_empty());
        assert_eq!(malformed.gas_used, DPOS_DEFAULT_METHOD_GAS);

        let mut nonpayable = dpos_call_request(
            0,
            dpos_eligibility_address_input(DPOS_IS_VALIDATOR_ELIGIBLE_SELECTOR, validator),
        );
        nonpayable.value = U256::one().into();
        let nonpayable = final_chain.call(nonpayable).unwrap();
        assert_eq!(nonpayable.code_err, "DPoS method is not payable");
        assert_eq!(nonpayable.gas_used, 0);

        let validator_info = final_chain
            .call(dpos_call_request(0, get_validator_input(validator)))
            .unwrap();
        assert_eq!(validator_info.code_err, "");
        assert_eq!(validator_info.code_retval.len(), 352);
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[0..32]),
            U256::from(32u64)
        );
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[32..64]),
            U256::from(10_000u64)
        );
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[64..96]),
            U256::zero()
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn eligibility_reads_use_delayed_threshold_and_jail_expiry_state() {
        let path = temp_db_path("eligibility-read-delayed-jail");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator = [0x17; 20];
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            1_000_000,
            0,
            vec![],
            vec![genesis_validator(validator, U256::from(1_000u64))],
            GenesisDposConfig {
                eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
                vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
                validator_maximum_stake: u256_to_big_endian(U256::from(10_000u64)),
                delegation_delay: 1,
                ..Default::default()
            },
            FinalChainRewardsConfig {
                magnolia_period: 0,
                cacti_period: 0,
                cornus_period: 0,
                ..Default::default()
            },
        )
        .unwrap();

        let mut delayed = final_chain.dpos_snapshot(0).unwrap();
        delayed.slashing_jail_blocks.insert(validator, 0);
        delayed.slashing_jailed_validators.push(validator);
        let after_expiry = delayed.clone();
        {
            let mut snapshots = final_chain.dpos_snapshots.lock().unwrap();
            snapshots.insert(0, delayed.clone());
            snapshots.insert(1, after_expiry);
        }

        let jailed = final_chain
            .call(dpos_call_request(
                1,
                dpos_eligibility_address_input(DPOS_IS_VALIDATOR_ELIGIBLE_SELECTOR, validator),
            ))
            .unwrap();
        assert_eq!(u256_from_big_endian(&jailed.code_retval), U256::zero());
        let jailed_votes = final_chain
            .call(dpos_call_request(
                1,
                dpos_eligibility_address_input(
                    DPOS_GET_VALIDATOR_ELIGIBLE_VOTES_SELECTOR,
                    validator,
                ),
            ))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&jailed_votes.code_retval),
            U256::zero()
        );

        let expired = final_chain
            .call(dpos_call_request(
                2,
                dpos_eligibility_address_input(DPOS_IS_VALIDATOR_ELIGIBLE_SELECTOR, validator),
            ))
            .unwrap();
        assert_eq!(u256_from_big_endian(&expired.code_retval), U256::one());

        let mut current = delayed.clone();
        current.total_stakes.insert(validator, Vec::new());
        current.vote_counts.insert(validator, 0);
        current.total_vote_count = 0;
        let frozen_read = final_chain
            .apply_dpos_eligibility_read(
                &delayed,
                1,
                DposTransaction::GetValidatorEligibleVotesCount(Ok(validator)),
            )
            .unwrap();
        let current_read = final_chain
            .apply_dpos_eligibility_read(
                &current,
                1,
                DposTransaction::GetValidatorEligibleVotesCount(Ok(validator)),
            )
            .unwrap();
        assert_eq!(u256_from_big_endian(&frozen_read.code_retval), U256::one());
        assert_eq!(
            u256_from_big_endian(&current_read.code_retval),
            U256::zero()
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

