    fn assert_finalize_block_executes_slashing(magnolia_period: u64, cacti_period: u64) {
        let path = temp_db_path("finalize-slashing-double-vote");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator_key = SigningKey::from_slice(&[0x51; 32]).unwrap();
        let validator_h160 = address_from_signing_key(&validator_key);
        let mut validator = [0u8; 20];
        validator.copy_from_slice(validator_h160.as_bytes());
        let submitter = [0x52; 20];
        let period = 1u64;
        let block_signing_key = SigningKey::from_slice(&[0x53; 32]).unwrap();
        let pbft = signed_pbft_block(&block_signing_key, period, 241);
        let sortition = legacy_vrf_sortition_rlp(period, 2, 4, 0x5a);
        let vote_a =
            signed_legacy_pbft_vote(&validator_key, H256::from_low_u64_be(100), &sortition);
        let vote_b =
            signed_legacy_pbft_vote(&validator_key, H256::from_low_u64_be(101), &sortition);
        let input = commit_double_voting_proof_input(&vote_a, &vote_b);
        let first_tx_rlp = vec![0xc1, 0xD1];
        let second_tx_rlp = vec![0xc1, 0xD2];
        let first_tx = test_transaction(
            0xD1,
            submitter,
            Some(SLASHING_CONTRACT_ADDRESS),
            0,
            U256::zero(),
            U256::zero(),
            100_000,
            input.clone(),
            first_tx_rlp.clone(),
        );
        let duplicate_tx = test_transaction(
            0xD2,
            submitter,
            Some(SLASHING_CONTRACT_ADDRESS),
            1,
            U256::zero(),
            U256::zero(),
            100_000,
            input,
            second_tx_rlp.clone(),
        );
        write_period_data(
            &storage,
            period,
            &pbft,
            &[first_tx_rlp.clone(), second_tx_rlp.clone()],
        );
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            300_000,
            0,
            vec![genesis_account(submitter, U256::from(1_000_000u64))],
            vec![genesis_validator(validator, U256::from(10_000u64))],
            GenesisDposConfig {
                eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
                vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
                validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
                minimum_deposit: vec![],
                commission_change_delta: 0,
                commission_change_frequency: 0,
                delegation_delay: 0,
                dag_vdf_sortition_total_vote_count_until_period: 0,
            },
            FinalChainRewardsConfig {
                magnolia_period,
                cacti_period,
                magnolia_jail_time: 2,
                cacti_jail_time: 2,
                ..Default::default()
            },
        )
        .unwrap();

        let (_header, receipts) = final_chain
            .finalize_block(pbft, vec![first_tx.clone(), duplicate_tx.clone()], vec![])
            .unwrap();
        let first_tx_gas = expected_native_contract_tx_gas(&final_chain, period, &first_tx);
        let duplicate_tx_gas = expected_native_contract_tx_gas(&final_chain, period, &duplicate_tx);

        assert_eq!(
            receipt_fields(&receipts[0]),
            (1, first_tx_gas, first_tx_gas)
        );
        assert_eq!(
            receipt_fields(&receipts[1]),
            (0, duplicate_tx_gas, first_tx_gas + duplicate_tx_gas)
        );
        let logs = receipt_logs(&receipts[0]);
        assert_eq!(logs.len(), 1);
        assert_eq!(logs[0].address, SLASHING_CONTRACT_ADDRESS);
        assert_eq!(
            logs[0].topics,
            vec![
                SLASHING_JAILED_TOPIC,
                address_topic(validator),
                u64_topic(period),
                u64_topic(period + 2)
            ]
        );
        assert_eq!(
            logs[0].data,
            abi_word_from_u64(u64::from(SLASHING_DOUBLE_VOTING_BEHAVIOUR)).to_vec()
        );
        assert_eq!(
            final_chain
                .dpos_eligible_vote_count(period, validator)
                .unwrap(),
            0
        );
        assert_eq!(
            final_chain.dpos_eligible_total_vote_count(period).unwrap(),
            0
        );
        let jail_block = final_chain
            .call(slashing_call_request(
                period,
                get_jail_block_input(validator),
            ))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&jail_block.code_retval),
            U256::from(period + 2)
        );
        let jailed_validators = final_chain
            .call(slashing_call_request(period, get_jailed_validators_input()))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&jailed_validators.code_retval[0..32]),
            U256::from(32)
        );
        assert_eq!(
            u256_from_big_endian(&jailed_validators.code_retval[32..64]),
            U256::from(1)
        );
        assert_eq!(&jailed_validators.code_retval[76..96], &validator);

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_executes_slashing_at_nonzero_activation_boundary() {
        assert_finalize_block_executes_slashing(1, 1);
    }

    #[test]
    fn finalize_block_executes_slashing_when_hardforks_activate_at_zero() {
        assert_finalize_block_executes_slashing(0, 0);
    }

    #[test]
    fn finalize_block_does_not_double_charge_duplicate_slashing_proof_value() {
        let path = temp_db_path("finalize-slashing-double-vote-duplicate-value");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let validator_key = SigningKey::from_slice(&[0x62; 32]).unwrap();
        let validator_h160 = address_from_signing_key(&validator_key);
        let mut validator = [0u8; 20];
        validator.copy_from_slice(validator_h160.as_bytes());
        let submitter = [0x63; 20];
        let period = 1u64;
        let block_signing_key = SigningKey::from_slice(&[0x64; 32]).unwrap();
        let pbft = signed_pbft_block(&block_signing_key, period, 243);
        let sortition = legacy_vrf_sortition_rlp(period, 2, 4, 0x5c);
        let vote_a =
            signed_legacy_pbft_vote(&validator_key, H256::from_low_u64_be(300), &sortition);
        let vote_b =
            signed_legacy_pbft_vote(&validator_key, H256::from_low_u64_be(301), &sortition);
        let input = commit_double_voting_proof_input(&vote_a, &vote_b);
        let first_value = U256::from(777u64);
        let duplicate_value = U256::from(888u64);
        let gas_price = U256::from(3u64);
        let first_tx = test_transaction(
            0xD4,
            submitter,
            Some(SLASHING_CONTRACT_ADDRESS),
            0,
            first_value,
            gas_price,
            100_000,
            input.clone(),
            vec![0xc1, 0xd4],
        );
        let duplicate_tx = test_transaction(
            0xD5,
            submitter,
            Some(SLASHING_CONTRACT_ADDRESS),
            1,
            duplicate_value,
            gas_price,
            100_000,
            input,
            vec![0xc1, 0xd5],
        );
        write_period_data(
            &storage,
            period,
            &pbft,
            &[first_tx.rlp.clone(), duplicate_tx.rlp.clone()],
        );
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            300_000,
            0,
            vec![genesis_account(submitter, U256::from(1_000_000u64))],
            vec![genesis_validator(validator, U256::from(10_000u64))],
            GenesisDposConfig {
                eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
                vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
                validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
                minimum_deposit: vec![],
                commission_change_delta: 0,
                commission_change_frequency: 0,
                delegation_delay: 0,
                dag_vdf_sortition_total_vote_count_until_period: 0,
            },
            FinalChainRewardsConfig {
                magnolia_period: 1,
                cacti_period: 1,
                magnolia_jail_time: 2,
                cacti_jail_time: 2,
                ..Default::default()
            },
        )
        .unwrap();

        let (_header, receipts) = final_chain
            .finalize_block(pbft, vec![first_tx.clone(), duplicate_tx.clone()], vec![])
            .unwrap();
        let first_tx_gas = expected_native_contract_tx_gas(&final_chain, period, &first_tx);
        let duplicate_tx_gas = expected_native_contract_tx_gas(&final_chain, period, &duplicate_tx);
        assert_eq!(
            receipt_fields(&receipts[0]),
            (1, first_tx_gas, first_tx_gas)
        );
        assert_eq!(
            receipt_fields(&receipts[1]),
            (0, duplicate_tx_gas, first_tx_gas + duplicate_tx_gas)
        );
        assert_eq!(
            balance_of(&final_chain, submitter),
            U256::from(1_000_000u64)
                .checked_sub(
                    (U256::from(first_tx_gas)
                        .checked_add(U256::from(duplicate_tx_gas))
                        .unwrap())
                    .checked_mul(gas_price)
                    .unwrap()
                )
                .expect("submitter sender balance must remain non-negative")
                - first_value
        );
        assert_eq!(
            balance_of(&final_chain, SLASHING_CONTRACT_ADDRESS),
            first_value
        );
        let slashing_account = final_chain
            .account(SLASHING_CONTRACT_ADDRESS)
            .unwrap()
            .unwrap();
        assert_eq!(slashing_account.nonce, 1);
        assert_eq!(*slashing_account.balance.as_u256(), first_value);

        let header_before_restart = final_chain.block_header(period).unwrap().unwrap();
        drop(final_chain);
        drop(storage);

        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let restart_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            300_000,
            0,
            vec![genesis_account(submitter, U256::from(1_000_000u64))],
            vec![genesis_validator(validator, U256::from(10_000u64))],
            GenesisDposConfig {
                eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
                vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
                validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
                minimum_deposit: vec![],
                commission_change_delta: 0,
                commission_change_frequency: 0,
                delegation_delay: 0,
                dag_vdf_sortition_total_vote_count_until_period: 0,
            },
            FinalChainRewardsConfig {
                magnolia_period: 1,
                cacti_period: 1,
                magnolia_jail_time: 2,
                cacti_jail_time: 2,
                ..Default::default()
            },
        )
        .unwrap();
        assert_eq!(
            restart_chain.block_header(period).unwrap().unwrap(),
            header_before_restart
        );
        assert_eq!(
            restart_chain
                .transaction_receipt_rlp(period, 1.into())
                .unwrap()
                .unwrap(),
            receipts[1].clone()
        );
        assert_eq!(
            restart_chain
                .account(SLASHING_CONTRACT_ADDRESS)
                .unwrap()
                .unwrap()
                .nonce,
            1
        );
        assert_eq!(
            balance_of(&restart_chain, SLASHING_CONTRACT_ADDRESS),
            first_value
        );
        assert_eq!(restart_chain.account(submitter).unwrap().unwrap().nonce, 2);

        drop(restart_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_executes_slashing_reads_with_value_and_failure_rollback() {
        let path = temp_db_path("finalize-slashing-read-transactions");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let sender = [0x81; 20];
        let validator = [0x82; 20];
        let period = 1u64;
        let block_signing_key = SigningKey::from_slice(&[0x83; 32]).unwrap();
        let pbft = signed_pbft_block(&block_signing_key, period, 245);
        let gas_price = U256::one();

        let jail_value = U256::from(111u64);
        let jailed_value = U256::from(222u64);
        let malformed_value = U256::from(333u64);
        let oog_value = U256::from(444u64);
        let jail_tx = test_transaction(
            0xE1,
            sender,
            Some(SLASHING_CONTRACT_ADDRESS),
            0,
            jail_value,
            gas_price,
            100_000,
            get_jail_block_input(validator),
            vec![0xc1, 0xe1],
        );
        let mut jailed_input = get_jailed_validators_input();
        jailed_input.extend_from_slice(&[0xaa, 0xbb]);
        let jailed_tx = test_transaction(
            0xE2,
            sender,
            Some(SLASHING_CONTRACT_ADDRESS),
            1,
            jailed_value,
            gas_price,
            100_000,
            jailed_input,
            vec![0xc1, 0xe2],
        );
        let malformed_tx = test_transaction(
            0xE3,
            sender,
            Some(SLASHING_CONTRACT_ADDRESS),
            2,
            malformed_value,
            gas_price,
            100_000,
            SLASHING_GET_JAIL_BLOCK_SELECTOR.to_vec(),
            vec![0xc1, 0xe3],
        );
        let oog_input = get_jail_block_input(validator);
        let oog_intrinsic_gas = intrinsic_gas(&oog_input, false).unwrap();
        let oog_tx = test_transaction(
            0xE4,
            sender,
            Some(SLASHING_CONTRACT_ADDRESS),
            3,
            oog_value,
            gas_price,
            oog_intrinsic_gas,
            oog_input,
            vec![0xc1, 0xe4],
        );
        let transactions = vec![
            jail_tx.clone(),
            jailed_tx.clone(),
            malformed_tx.clone(),
            oog_tx.clone(),
        ];
        write_period_data(
            &storage,
            period,
            &pbft,
            &transactions
                .iter()
                .map(|transaction| transaction.rlp.clone())
                .collect::<Vec<_>>(),
        );
        let initial_balance = U256::from(2_000_000u64);
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            500_000,
            0,
            vec![genesis_account(sender, initial_balance)],
            vec![],
            GenesisDposConfig::default(),
            FinalChainRewardsConfig {
                magnolia_period: 0,
                cacti_period: u64::MAX,
                ..Default::default()
            },
        )
        .unwrap();

        let jail_gas = expected_native_contract_tx_gas(&final_chain, period, &jail_tx);
        let jailed_gas = expected_native_contract_tx_gas(&final_chain, period, &jailed_tx);
        let malformed_gas = expected_native_contract_tx_gas(&final_chain, period, &malformed_tx);
        let (_header, receipts) = final_chain
            .finalize_block(pbft, transactions, vec![])
            .unwrap();

        assert_eq!(receipt_fields(&receipts[0]), (1, jail_gas, jail_gas));
        assert_eq!(
            receipt_fields(&receipts[1]),
            (1, jailed_gas, jail_gas + jailed_gas)
        );
        assert_eq!(
            receipt_fields(&receipts[2]),
            (0, malformed_gas, jail_gas + jailed_gas + malformed_gas)
        );
        assert_eq!(
            receipt_fields(&receipts[3]),
            (
                0,
                oog_intrinsic_gas,
                jail_gas + jailed_gas + malformed_gas + oog_intrinsic_gas
            )
        );
        assert!(
            receipts
                .iter()
                .all(|receipt| receipt_logs(receipt).is_empty())
        );
        assert_eq!(final_chain.account(sender).unwrap().unwrap().nonce, 4);
        assert_eq!(
            balance_of(&final_chain, sender),
            initial_balance
                - U256::from(jail_gas + jailed_gas + malformed_gas + oog_intrinsic_gas)
                - jail_value
                - jailed_value
        );
        assert_eq!(
            balance_of(&final_chain, SLASHING_CONTRACT_ADDRESS),
            jail_value + jailed_value
        );
        assert_eq!(
            final_chain
                .account(SLASHING_CONTRACT_ADDRESS)
                .unwrap()
                .unwrap()
                .nonce,
            0
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_activates_slashing_read_gas_at_magnolia_boundary() {
        let path = temp_db_path("finalize-slashing-read-activation");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let sender = [0x84; 20];
        let signing_key = SigningKey::from_slice(&[0x85; 32]).unwrap();
        let initial_balance = U256::from(1_000_000u64);
        let value_before = U256::from(10u64);
        let value_at = U256::from(20u64);
        let mut read_input = get_jailed_validators_input();
        read_input.push(0xcc);
        let before_tx = test_transaction(
            0xE5,
            sender,
            Some(SLASHING_CONTRACT_ADDRESS),
            0,
            value_before,
            U256::one(),
            100_000,
            read_input.clone(),
            vec![0xc1, 0xe5],
        );
        let at_tx = test_transaction(
            0xE6,
            sender,
            Some(SLASHING_CONTRACT_ADDRESS),
            1,
            value_at,
            U256::one(),
            100_000,
            read_input,
            vec![0xc1, 0xe6],
        );
        let before_pbft = signed_pbft_block(&signing_key, 1, 246);
        write_period_data(
            &storage,
            1,
            &before_pbft,
            std::slice::from_ref(&before_tx.rlp),
        );
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            200_000,
            0,
            vec![genesis_account(sender, initial_balance)],
            vec![],
            GenesisDposConfig::default(),
            FinalChainRewardsConfig {
                magnolia_period: 2,
                cacti_period: u64::MAX,
                ..Default::default()
            },
        )
        .unwrap();

        let before_intrinsic = intrinsic_gas(&before_tx.data, false).unwrap();
        let (_, before_receipts) = final_chain
            .finalize_block(before_pbft, vec![before_tx], vec![])
            .unwrap();
        assert_eq!(
            receipt_fields(&before_receipts[0]),
            (1, before_intrinsic, before_intrinsic)
        );

        let at_pbft = signed_pbft_block(&signing_key, 2, 247);
        write_period_data(&storage, 2, &at_pbft, std::slice::from_ref(&at_tx.rlp));
        let at_gas = expected_native_contract_tx_gas(&final_chain, 2, &at_tx);
        let (_, at_receipts) = final_chain
            .finalize_block(at_pbft, vec![at_tx], vec![])
            .unwrap();
        assert_eq!(receipt_fields(&at_receipts[0]), (1, at_gas, at_gas));
        assert_eq!(at_gas, before_intrinsic + SLASHING_GET_METHOD_GAS);
        assert_eq!(
            balance_of(&final_chain, SLASHING_CONTRACT_ADDRESS),
            value_before + value_at
        );
        assert_eq!(
            final_chain
                .account(SLASHING_CONTRACT_ADDRESS)
                .unwrap()
                .unwrap()
                .nonce,
            0
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

