    #[test]
    fn finalize_block_supports_dpos_action_insufficient_gas_advances_nonce() {
        let path = temp_db_path("finalize-dpos-action-insufficient-gas");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let period = 1u64;
        let sender = [0xB0; 20];
        let validator = [0xB1; 20];
        let signing_key = SigningKey::from_slice(&[29u8; 32]).unwrap();
        let pbft = signed_pbft_block(&signing_key, period, 223);
        let mut action_tx = test_transaction(
            0xB3,
            sender,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            U256::zero(),
            U256::from(2u64),
            100_000,
            set_validator_info_input(validator, "bad action", "insufficient gas"),
            vec![0xc1, 0xB3],
        );
        let tx_intrinsic_gas = intrinsic_gas(&action_tx.data, false).unwrap();
        let action_insufficient_tx_gas_limit = tx_intrinsic_gas;
        action_tx.gas_limit = action_insufficient_tx_gas_limit;

        write_period_data(
            &storage,
            period,
            &pbft,
            std::slice::from_ref(&action_tx.rlp),
        );
        let final_chain = FinalChain::new(
            storage.clone(),
            100_000,
            0,
            vec![genesis_account(sender, U256::from(1_000_000u64))],
            vec![],
            GenesisDposConfig::default(),
        )
        .unwrap();

        let required_gas = expected_native_contract_tx_gas(&final_chain, period, &action_tx);
        let (_header_rlp, receipts) = final_chain
            .finalize_block(pbft, vec![action_tx], vec![])
            .unwrap();
        assert!(required_gas > action_insufficient_tx_gas_limit);

        assert_eq!(
            receipt_fields(&receipts[0]),
            (
                0,
                action_insufficient_tx_gas_limit,
                action_insufficient_tx_gas_limit
            )
        );
        let sender_account = final_chain.account(sender).unwrap().unwrap();
        assert_eq!(sender_account.nonce, 1);
        assert_eq!(
            *sender_account.balance.as_u256(),
            U256::from(1_000_000u64) - U256::from(action_insufficient_tx_gas_limit * 2u64)
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_supports_validator_owner_updates_and_failed_receipts() {
        let path = temp_db_path("finalize-dpos-validator-owner-updates");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let period = 1u64;
        let validator = [0x30; 20];
        let owner = [0x31; 20];
        let wrong_owner = [0x32; 20];
        let genesis_validator = genesis_validator_with_metadata(
            validator,
            U256::from(10_000u64),
            owner,
            1_000,
            "old description",
            "old endpoint",
        );
        let genesis_dpos_config = GenesisDposConfig {
            eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
            vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
            validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
            minimum_deposit: vec![],
            commission_change_delta: 500,
            commission_change_frequency: 0,
            delegation_delay: 0,
            dag_vdf_sortition_total_vote_count_until_period: 0,
        };
        let signing_key = SigningKey::from_slice(&[34u8; 32]).unwrap();
        let pbft = signed_pbft_block(&signing_key, period, 231);
        let failed_info_tx = test_transaction(
            0xA0,
            wrong_owner,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            U256::zero(),
            U256::zero(),
            100_000,
            set_validator_info_input(validator, "bad description", "bad endpoint"),
            vec![0xc1, 0xA0],
        );
        let info_tx = test_transaction(
            0xA1,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            U256::zero(),
            U256::zero(),
            100_000,
            set_validator_info_input(validator, "new description", "new endpoint"),
            vec![0xc1, 0xA1],
        );
        let commission_tx = test_transaction(
            0xA2,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            1,
            U256::zero(),
            U256::zero(),
            100_000,
            set_commission_input(validator, 1_500),
            vec![0xc1, 0xA2],
        );
        write_period_data(
            &storage,
            period,
            &pbft,
            &[
                failed_info_tx.rlp.clone(),
                info_tx.rlp.clone(),
                commission_tx.rlp.clone(),
            ],
        );
        let final_chain = FinalChain::new(
            storage.clone(),
            300_000,
            0,
            vec![
                genesis_account(owner, U256::from(1_000_000u64)),
                genesis_account(wrong_owner, U256::from(1_000_000u64)),
            ],
            vec![genesis_validator.clone()],
            genesis_dpos_config.clone(),
        )
        .unwrap();

        let (_header_rlp, receipts) = final_chain
            .finalize_block(
                pbft,
                vec![
                    failed_info_tx.clone(),
                    info_tx.clone(),
                    commission_tx.clone(),
                ],
                vec![],
            )
            .unwrap();
        let failed_info_tx_gas =
            expected_native_contract_tx_gas(&final_chain, period, &failed_info_tx);
        let info_tx_gas = expected_native_contract_tx_gas(&final_chain, period, &info_tx);
        let commission_tx_gas =
            expected_native_contract_tx_gas(&final_chain, period, &commission_tx);
        let info_tx_cumulative_gas = failed_info_tx_gas + info_tx_gas;
        let commission_tx_cumulative_gas = info_tx_cumulative_gas + commission_tx_gas;
        assert_eq!(
            receipt_fields(&receipts[0]),
            (0, failed_info_tx_gas, failed_info_tx_gas)
        );
        assert!(receipt_logs(&receipts[0]).is_empty());
        assert_eq!(
            receipt_fields(&receipts[1]),
            (1, info_tx_gas, info_tx_cumulative_gas)
        );
        let info_logs = receipt_logs(&receipts[1]);
        assert_eq!(info_logs.len(), 1);
        assert_eq!(info_logs[0], dpos_validator_info_set_log(validator));
        assert_eq!(
            receipt_fields(&receipts[2]),
            (1, commission_tx_gas, commission_tx_cumulative_gas)
        );
        let commission_logs = receipt_logs(&receipts[2]);
        assert_eq!(commission_logs.len(), 1);
        assert_eq!(
            commission_logs[0],
            dpos_commission_set_log(validator, 1_500).unwrap()
        );

        let validator_info = final_chain
            .call(dpos_call_request(period, get_validator_input(validator)))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[96..128]),
            U256::from(1_500u64)
        );
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[128..160]),
            U256::from(period)
        );
        let description_offset =
            u256_from_big_endian(&validator_info.code_retval[224..256]).as_usize();
        let endpoint_offset =
            u256_from_big_endian(&validator_info.code_retval[256..288]).as_usize();
        assert_abi_string_tail(
            &validator_info.code_retval,
            32,
            description_offset,
            "new description",
        );
        assert_abi_string_tail(
            &validator_info.code_retval,
            32,
            endpoint_offset,
            "new endpoint",
        );

        drop(final_chain);
        let final_chain = FinalChain::new(
            storage.clone(),
            300_000,
            0,
            vec![
                genesis_account(owner, U256::from(1_000_000u64)),
                genesis_account(wrong_owner, U256::from(1_000_000u64)),
            ],
            vec![genesis_validator],
            genesis_dpos_config,
        )
        .unwrap();
        let validator_info = final_chain
            .call(dpos_call_request(period, get_validator_input(validator)))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[128..160]),
            U256::from(period)
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

