    #[test]
    fn dpos_snapshot_with_delegation_delay_persists_through_restart() {
        let path = temp_db_path("dpos-delegation-delay-restart");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let period_one = 1u64;
        let period_two = 2u64;
        let period_three = 3u64;
        let owner = [0x01; 20];
        let signing_key = SigningKey::from_slice(&[0x77; 32]).unwrap();
        let validator = address_from_signing_key(&signing_key).into();
        let proof = register_validator_proof(&signing_key, validator, None);
        let genesis_dpos_config = GenesisDposConfig {
            eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
            vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
            validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
            minimum_deposit: vec![],
            commission_change_delta: 0,
            commission_change_frequency: 0,
            delegation_delay: 2,
            dag_vdf_sortition_total_vote_count_until_period: 0,
        };

        let block_one = signed_pbft_block(&signing_key, period_one, 101);
        let block_two = signed_pbft_block(&signing_key, period_two, 102);
        let block_three = signed_pbft_block(&signing_key, period_three, 103);

        let register_input = register_validator_input(
            validator,
            &proof,
            [0xA5; 32],
            10,
            "delegation delay validator",
            "delegation delay endpoint",
        );
        let register_tx = test_transaction(
            0xE1,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            U256::from(5_000u64),
            U256::from(2u64),
            150_000,
            register_input,
            vec![0xc1, 0xe1],
        );
        let delegate_tx = test_transaction(
            0xE2,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            1,
            U256::from(1_000u64),
            U256::from(2u64),
            100_000,
            delegate_input(validator),
            vec![0xc1, 0xe2],
        );

        write_period_data(
            &storage,
            period_one,
            &block_one,
            std::slice::from_ref(&register_tx.rlp),
        );
        write_period_data(
            &storage,
            period_two,
            &block_two,
            std::slice::from_ref(&delegate_tx.rlp),
        );
        write_period_data(&storage, period_three, &block_three, &[]);

        let final_chain = FinalChain::new(
            storage.clone(),
            300_000,
            0,
            vec![genesis_account(owner, U256::from(1_000_000u64))],
            vec![],
            genesis_dpos_config.clone(),
        )
        .unwrap();

        let _ = final_chain
            .finalize_block(block_one, vec![register_tx], vec![])
            .unwrap();
        let _ = final_chain
            .finalize_block(block_two, vec![delegate_tx], vec![])
            .unwrap();

        let period_one_final_snapshot = final_chain
            .dpos_snapshot_at_finalized_block(period_one)
            .unwrap();
        let period_two_final_snapshot = final_chain
            .dpos_snapshot_at_finalized_block(period_two)
            .unwrap();
        let delayed_period_two_snapshot = final_chain.dpos_snapshot(period_two).unwrap();
        assert_eq!(
            u256_from_big_endian(
                period_one_final_snapshot
                    .total_stakes
                    .get(&validator)
                    .expect("missing validator stake in block-one finalized snapshot"),
            ),
            U256::from(5_000u64)
        );
        assert_eq!(period_one_final_snapshot.total_vote_count, 5);
        assert_eq!(
            u256_from_big_endian(
                period_two_final_snapshot
                    .total_stakes
                    .get(&validator)
                    .expect("missing validator stake in block-two finalized snapshot"),
            ),
            U256::from(6_000u64),
        );
        assert_eq!(period_two_final_snapshot.total_vote_count, 6);
        assert_eq!(delayed_period_two_snapshot.total_stakes.len(), 0);

        drop(final_chain);
        drop(storage);

        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let final_chain = FinalChain::new(
            storage.clone(),
            300_000,
            0,
            vec![genesis_account(owner, U256::from(1_000_000u64))],
            vec![],
            genesis_dpos_config,
        )
        .unwrap();

        assert_eq!(final_chain.last_block_number().unwrap(), period_two);
        let reloaded_period_two_snapshot = final_chain
            .dpos_snapshot_at_finalized_block(period_two)
            .unwrap();
        assert_eq!(
            u256_from_big_endian(
                reloaded_period_two_snapshot
                    .total_stakes
                    .get(&validator)
                    .expect("missing validator stake in reloaded block-two snapshot"),
            ),
            U256::from(6_000u64),
        );
        assert_eq!(reloaded_period_two_snapshot.total_vote_count, 6);

        let (_, _receipts) = final_chain
            .finalize_block(block_three, vec![], vec![])
            .unwrap();

        let persisted_period_three_snapshot = final_chain
            .dpos_snapshot_at_finalized_block(period_three)
            .unwrap();
        let delayed_period_three_snapshot = final_chain.dpos_snapshot(period_three).unwrap();
        assert_eq!(
            u256_from_big_endian(
                persisted_period_three_snapshot
                    .total_stakes
                    .get(&validator)
                    .expect("missing validator stake in persisted block-three snapshot"),
            ),
            U256::from(6_000u64),
        );
        assert_eq!(persisted_period_three_snapshot.total_vote_count, 6);
        assert_eq!(
            u256_from_big_endian(
                delayed_period_three_snapshot
                    .total_stakes
                    .get(&validator)
                    .expect("missing validator stake in delayed block-three snapshot"),
            ),
            U256::from(5_000u64),
        );
        assert_eq!(delayed_period_three_snapshot.total_vote_count, 5);

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_registers_dpos_validator_snapshot() {
        let path = temp_db_path("finalize-dpos-register-validator");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let period = 1u64;
        let owner = [0x31; 20];
        let signing_key = SigningKey::from_slice(&[15u8; 32]).unwrap();
        let validator = address_from_signing_key(&signing_key).into();
        let proof = register_validator_proof(&signing_key, validator, None);
        let vrf_key = [0xA5; 32];
        let stake = U256::from(5_000u64);
        let genesis_dpos_config = GenesisDposConfig {
            eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
            vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
            validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
            minimum_deposit: vec![],
            commission_change_delta: 0,
            commission_change_frequency: 0,
            delegation_delay: 0,
            dag_vdf_sortition_total_vote_count_until_period: 0,
        };
        let pbft_block = signed_pbft_block(&signing_key, period, 140);
        let transaction_rlp = vec![0xc1, 0x91];
        let input = register_validator_input(
            validator,
            &proof,
            vrf_key,
            10,
            "test validator",
            "test endpoint",
        );
        let transaction = test_transaction(
            0xA7,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            stake,
            U256::from(2u64),
            150_000,
            input,
            transaction_rlp.clone(),
        );
        write_period_data(
            &storage,
            period,
            &pbft_block,
            std::slice::from_ref(&transaction_rlp),
        );
        let final_chain = FinalChain::new(
            storage.clone(),
            200_000,
            0,
            vec![genesis_account(owner, U256::from(1_000_000u64))],
            vec![],
            genesis_dpos_config.clone(),
        )
        .unwrap();

        let (_header_rlp, receipts) = final_chain
            .finalize_block(pbft_block, vec![transaction.clone()], vec![])
            .unwrap();
        let transaction_gas = expected_native_contract_tx_gas(&final_chain, period, &transaction);

        assert_eq!(
            receipt_fields(&receipts[0]),
            (1, transaction_gas, transaction_gas)
        );
        let logs = receipt_logs(&receipts[0]);
        assert_eq!(logs.len(), 2);
        assert_eq!(
            logs[0],
            ReceiptLog {
                address: DPOS_CONTRACT_ADDRESS,
                topics: vec![DPOS_VALIDATOR_REGISTERED_TOPIC, address_topic(validator)],
                data: Vec::new(),
            }
        );
        assert_dpos_amount_log(
            &logs[1],
            DPOS_DELEGATED_TOPIC,
            vec![address_topic(owner), address_topic(validator)],
            stake,
        );
        assert_eq!(
            final_chain
                .dpos_eligible_vote_count(period, validator)
                .unwrap(),
            5
        );
        assert_eq!(
            final_chain.dpos_eligible_total_vote_count(period).unwrap(),
            5
        );
        assert!(final_chain.dpos_is_eligible(period, validator).unwrap());
        assert_eq!(final_chain.vrf_key(validator).unwrap(), Some(vrf_key));
        let validator_info = final_chain
            .call(dpos_call_request(period, get_validator_input(validator)))
            .unwrap();
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[32..64]),
            stake
        );
        assert_eq!(
            u256_from_big_endian(&validator_info.code_retval[96..128]),
            U256::from(10u64)
        );
        assert_eq!(
            &validator_info.code_retval[192..224],
            &abi_word_from_address(owner)
        );
        let register_topic_bloom = bloom_query_for_value(&DPOS_VALIDATOR_REGISTERED_TOPIC);
        assert_eq!(
            final_chain
                .with_block_bloom(&register_topic_bloom, period, period)
                .unwrap(),
            vec![period]
        );
        assert!(
            final_chain
                .with_block_bloom(&register_topic_bloom, period + 1, period + 1)
                .unwrap()
                .is_empty()
        );
        let pbft_author: [u8; 20] = address_from_signing_key(&signing_key).into();
        let author_bloom = bloom_query_for_value(&pbft_author);
        assert_eq!(
            final_chain
                .with_block_bloom(&author_bloom, period, period)
                .unwrap(),
            vec![period]
        );

        drop(final_chain);
        drop(storage);

        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let final_chain = FinalChain::new(
            storage.clone(),
            300_000,
            0,
            vec![genesis_account(owner, U256::from(1_000_000u64))],
            vec![],
            genesis_dpos_config,
        )
        .unwrap();
        assert_eq!(
            final_chain
                .dpos_eligible_vote_count(period, validator)
                .unwrap(),
            5
        );
        assert_eq!(final_chain.vrf_key(validator).unwrap(), Some(vrf_key));
        let facts = final_chain
            .dag_dpos_authorization_facts(period, validator)
            .unwrap();
        assert_eq!(facts.vrf_key, Some(vrf_key));
        assert_eq!(facts.sender_eligible_vote_count, 5);
        assert_eq!(facts.eligibility_status, DAG_VERIFY_DPOS_STATUS_ELIGIBLE);
        assert_eq!(
            final_chain
                .with_block_bloom(
                    &bloom_query_for_value(&DPOS_VALIDATOR_REGISTERED_TOPIC),
                    period,
                    period
                )
                .unwrap(),
            vec![period]
        );
        let genesis_facts = final_chain
            .dag_dpos_authorization_facts(0, validator)
            .unwrap();
        assert_eq!(genesis_facts.vrf_key, None);
        assert!(!genesis_facts.vrf_key_found);
        assert_eq!(
            genesis_facts.eligibility_status,
            DAG_VERIFY_DPOS_STATUS_NOT_CHECKED
        );

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

