    #[test]
    fn finalize_block_redelegate_to_maxed_destination_rolls_back_without_state_mutation() {
        let path = temp_db_path("finalize-dpos-redelegate-maxed-destination-failure");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let period = 1u64;
        let first_validator_key = SigningKey::from_slice(&[19u8; 32]).unwrap();
        let second_validator_key = SigningKey::from_slice(&[20u8; 32]).unwrap();
        let pbft_signing_key = SigningKey::from_slice(&[21u8; 32]).unwrap();
        let first_validator = address_from_signing_key(&first_validator_key).into();
        let second_validator = address_from_signing_key(&second_validator_key).into();
        let first_validator_proof =
            register_validator_proof(&first_validator_key, first_validator, None);
        let second_validator_proof =
            register_validator_proof(&second_validator_key, second_validator, None);
        let transfer_receiver = [0x46; 20];
        let owner = first_validator;
        let gas_price = U256::from(2u64);
        let owner_balance_before = U256::from(1_000_000u64);
        let genesis_dpos_config = GenesisDposConfig {
            eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
            vote_eligibility_balance_step: u256_to_big_endian(U256::from(1_000u64)),
            validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
            minimum_deposit: vec![],
            commission_change_delta: 0,
            commission_change_frequency: 0,
            delegation_delay: 0,
            dag_vdf_sortition_total_vote_count_until_period: 0,
        };
        let pbft_block = signed_pbft_block(&pbft_signing_key, period, 152);

        let register_first_tx = test_transaction(
            0xB0,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            U256::from(10_000u64),
            gas_price,
            150_000,
            register_validator_input(
                first_validator,
                &first_validator_proof,
                [0xA5; 32],
                10,
                "first",
                "endpoint",
            ),
            vec![0xc1, 0xa1],
        );
        let register_second_tx = test_transaction(
            0xB1,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            1,
            U256::from(30_000u64),
            gas_price,
            150_000,
            register_validator_input(
                second_validator,
                &second_validator_proof,
                [0xA6; 32],
                10,
                "second",
                "endpoint",
            ),
            vec![0xc1, 0xa2],
        );
        let redelegate_tx = test_transaction(
            0xB2,
            owner,
            Some(DPOS_CONTRACT_ADDRESS),
            2,
            U256::zero(),
            gas_price,
            150_000,
            redelegate_input(first_validator, second_validator, U256::from(1_000u64)),
            vec![0xc1, 0xa3],
        );
        let transfer_tx = test_transaction(
            0xB3,
            owner,
            Some(transfer_receiver),
            3,
            U256::from(25_000u64),
            gas_price,
            100_000,
            vec![],
            vec![0xc1, 0xb3],
        );

        write_period_data(
            &storage,
            period,
            &pbft_block,
            &[
                register_first_tx.rlp.clone(),
                register_second_tx.rlp.clone(),
                redelegate_tx.rlp.clone(),
                transfer_tx.rlp.clone(),
            ],
        );
        let final_chain = FinalChain::new(
            storage.clone(),
            400_000,
            0,
            vec![genesis_account(owner, owner_balance_before)],
            vec![],
            genesis_dpos_config,
        )
        .unwrap();

        let register_first_tx_gas =
            expected_native_contract_tx_gas(&final_chain, period, &register_first_tx);
        let register_second_tx_gas =
            expected_native_contract_tx_gas(&final_chain, period, &register_second_tx);
        let redelegate_tx_gas =
            expected_native_contract_tx_gas(&final_chain, period, &redelegate_tx);
        let transfer_tx_gas = expected_native_contract_tx_gas(&final_chain, period, &transfer_tx);
        let total_gas_cost =
            register_first_tx_gas + register_second_tx_gas + redelegate_tx_gas + transfer_tx_gas;

        let expected_snapshot_first_stake = U256::from(10_000u64);
        let expected_snapshot_second_stake = U256::from(30_000u64);

        let (_header_rlp, receipts) = final_chain
            .finalize_block(
                pbft_block,
                vec![
                    register_first_tx,
                    register_second_tx,
                    redelegate_tx,
                    transfer_tx,
                ],
                vec![],
            )
            .unwrap();

        assert_eq!(receipts.len(), 4);
        assert_eq!(
            receipt_fields(&receipts[0]),
            (1, register_first_tx_gas, register_first_tx_gas)
        );
        assert_eq!(
            receipt_fields(&receipts[1]),
            (
                1,
                register_second_tx_gas,
                register_first_tx_gas + register_second_tx_gas
            )
        );
        assert_eq!(
            receipt_fields(&receipts[2]),
            (
                0,
                redelegate_tx_gas,
                register_first_tx_gas + register_second_tx_gas + redelegate_tx_gas
            )
        );
        assert!(
            receipt_logs(&receipts[2]).is_empty(),
            "failed redelegation must emit no logs"
        );
        assert_eq!(
            receipt_fields(&receipts[3]),
            (
                1,
                transfer_tx_gas,
                register_first_tx_gas
                    + register_second_tx_gas
                    + redelegate_tx_gas
                    + transfer_tx_gas
            )
        );

        let snapshot = final_chain.dpos_snapshot(period).unwrap();
        assert_eq!(
            u256_from_big_endian(
                snapshot
                    .total_stakes
                    .get(&first_validator)
                    .expect("missing first validator stake"),
            ),
            expected_snapshot_first_stake
        );
        assert_eq!(
            u256_from_big_endian(
                snapshot
                    .total_stakes
                    .get(&second_validator)
                    .expect("missing second validator stake"),
            ),
            expected_snapshot_second_stake
        );
        assert_eq!(
            u256_from_big_endian(
                snapshot
                    .delegations
                    .get(&first_validator)
                    .expect("missing first validator delegations")
                    .get(&first_validator)
                    .expect("missing first validator self delegation"),
            ),
            expected_snapshot_first_stake
        );
        assert_eq!(
            u256_from_big_endian(
                snapshot
                    .delegations
                    .get(&second_validator)
                    .expect("missing second validator delegations")
                    .get(&owner)
                    .expect("missing second registration owner delegation"),
            ),
            expected_snapshot_second_stake,
            "failed redelegation must restore the destination registration delegation"
        );
        assert_eq!(snapshot.total_vote_count, 40);

        let expected_sender_balance = owner_balance_before
            - U256::from(10_000u64)
            - U256::from(30_000u64)
            - U256::from(total_gas_cost) * gas_price
            - U256::from(25_000u64);
        assert_eq!(balance_of(&final_chain, owner), expected_sender_balance);
        assert_eq!(
            balance_of(&final_chain, transfer_receiver),
            U256::from(25_000u64)
        );
        assert_eq!(final_chain.account(owner).unwrap().unwrap().nonce, 4);

        drop(final_chain);
        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

    #[test]
    fn finalize_block_applies_redelegate_correction_at_activation_block() {
        let path = temp_db_path("finalize-dpos-redelegate-hardfork-fix");
        let storage = Arc::new(Storage::new(Config::new(path.clone())).unwrap());
        let period_one = 1u64;
        let period_two = 2u64;
        let period_three = 3u64;
        let validator_key = SigningKey::from_slice(&[0xD1u8; 32]).unwrap();
        let validator: [u8; 20] = address_from_signing_key(&validator_key).into();
        let owner_key = SigningKey::from_slice(&[0xD0u8; 32]).unwrap();
        let owner: [u8; 20] = address_from_signing_key(&owner_key).into();
        let pbft_signing_key = SigningKey::from_slice(&[0xD2u8; 32]).unwrap();
        let period_one_block = signed_pbft_block(&pbft_signing_key, period_one, 201);
        let period_two_block = signed_pbft_block(&pbft_signing_key, period_two, 202);
        let period_three_block = signed_pbft_block(&pbft_signing_key, period_three, 203);
        let pre_fix_redelegation = test_transaction(
            0xD3,
            validator,
            Some(DPOS_CONTRACT_ADDRESS),
            0,
            U256::zero(),
            U256::zero(),
            150_000,
            redelegate_input(validator, validator, U256::from(1_000u64)),
            vec![0xc1, 0xD3],
        );
        let fix_block_redelegation = test_transaction(
            0xD4,
            validator,
            Some(DPOS_CONTRACT_ADDRESS),
            1,
            U256::zero(),
            U256::zero(),
            150_000,
            redelegate_input(validator, validator, U256::from(1_000u64)),
            vec![0xc1, 0xD4],
        );
        let post_fix_redelegation = test_transaction(
            0xD5,
            validator,
            Some(DPOS_CONTRACT_ADDRESS),
            2,
            U256::zero(),
            U256::zero(),
            150_000,
            redelegate_input(validator, validator, U256::from(1_000u64)),
            vec![0xc1, 0xD5],
        );
        let post_fix_claim = test_transaction(
            0xD6,
            validator,
            Some(DPOS_CONTRACT_ADDRESS),
            3,
            U256::zero(),
            U256::zero(),
            150_000,
            claim_rewards_input(validator),
            vec![0xc1, 0xD6],
        );
        write_period_data(
            &storage,
            period_one,
            &period_one_block,
            &[pre_fix_redelegation.rlp.clone()],
        );
        write_period_data(
            &storage,
            period_two,
            &period_two_block,
            &[fix_block_redelegation.rlp.clone()],
        );
        write_period_data(
            &storage,
            period_three,
            &period_three_block,
            &[
                post_fix_redelegation.rlp.clone(),
                post_fix_claim.rlp.clone(),
            ],
        );
        let genesis_dpos_config = GenesisDposConfig {
            eligibility_balance_threshold: u256_to_big_endian(U256::from(1_000u64)),
            vote_eligibility_balance_step: u256_to_big_endian(U256::from(10_000u64)),
            validator_maximum_stake: u256_to_big_endian(U256::from(30_000u64)),
            minimum_deposit: vec![],
            commission_change_delta: 0,
            commission_change_frequency: 0,
            delegation_delay: 0,
            dag_vdf_sortition_total_vote_count_until_period: 0,
        };
        let rewards_config = FinalChainRewardsConfig {
            fix_redelegate_block_num: period_two,
            redelegations: vec![RedelegationCorrection {
                validator,
                delegator: validator,
                amount: u256_to_big_endian(U256::from(1_000u64)),
            }],
            ..Default::default()
        };
        let rewards_config_clone = rewards_config.clone();
        let mut genesis_validator = genesis_validator_with_metadata(
            validator,
            U256::from(15_000u64),
            validator,
            2_500,
            "validator",
            "endpoint",
        );
        genesis_validator.metadata.owner = owner;
        genesis_validator.delegations = vec![
            (owner, u256_to_big_endian(U256::from(10_000u64))),
            (validator, u256_to_big_endian(U256::from(5_000u64))),
        ];
        let genesis_validator_clone = genesis_validator.clone();
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            200_000,
            0,
            vec![
                genesis_account(owner, U256::from(11_000u64)),
                genesis_account(validator, U256::from(2_000_000u64)),
            ],
            vec![genesis_validator_clone],
            genesis_dpos_config.clone(),
            rewards_config_clone,
        )
        .unwrap();
        final_chain
            .dpos_snapshots
            .lock()
            .unwrap()
            .get_mut(&0)
            .unwrap()
            .delegator_rewards
            .insert(validator, u256_to_big_endian(U256::from(1_000u64)));
        let validator_balance_before = balance_of(&final_chain, validator);

        let _ = final_chain
            .finalize_block(period_one_block, vec![pre_fix_redelegation], vec![])
            .unwrap();

        let snapshot_one = final_chain.dpos_snapshot(period_one).unwrap();
        assert_eq!(
            u256_from_big_endian(
                snapshot_one
                    .total_stakes
                    .get(&validator)
                    .expect("missing first validator stake"),
            ),
            U256::from(16_000u64)
        );
        assert_eq!(snapshot_one.total_vote_count, 1);
        assert_eq!(snapshot_one.vote_counts.get(&validator), Some(&1));
        assert_eq!(
            snapshot_one
                .delegator_rewards
                .get(&validator)
                .map(|rewards| u256_from_big_endian(rewards)),
            Some(U256::from(1_000u64))
        );
        assert_eq!(
            balance_of(&final_chain, validator),
            validator_balance_before + U256::from(333u64)
        );
        let (_, period_two_receipts) = final_chain
            .finalize_block(period_two_block, vec![fix_block_redelegation], vec![])
            .unwrap();
        assert_eq!(receipt_fields(&period_two_receipts[0]).0, 1);
        let snapshot_two = final_chain.dpos_snapshot(period_two).unwrap();
        assert_eq!(
            u256_from_big_endian(
                snapshot_two
                    .total_stakes
                    .get(&validator)
                    .expect("missing second validator stake"),
            ),
            U256::from(16_000u64)
        );
        assert_eq!(snapshot_two.total_vote_count, 1);
        assert_eq!(snapshot_two.vote_counts.get(&validator), Some(&1));
        assert_eq!(
            snapshot_two
                .delegator_rewards
                .get(&validator)
                .map(|rewards| u256_from_big_endian(rewards)),
            Some(U256::from(1_000u64))
        );
        assert_eq!(
            balance_of(&final_chain, validator),
            validator_balance_before + U256::from(333u64)
        );

        let (_, receipts) = final_chain
            .finalize_block(
                period_three_block,
                vec![post_fix_redelegation, post_fix_claim],
                vec![],
            )
            .unwrap();
        assert_eq!(receipt_fields(&receipts[0]).0, 0);
        assert_eq!(receipt_fields(&receipts[1]).0, 1);
        let snapshot_three = final_chain.dpos_snapshot(period_three).unwrap();
        assert_eq!(
            u256_from_big_endian(
                snapshot_three
                    .total_stakes
                    .get(&validator)
                    .expect("missing third validator stake"),
            ),
            U256::from(16_000u64)
        );
        assert_eq!(snapshot_three.total_vote_count, 1);
        assert_eq!(snapshot_three.vote_counts.get(&validator), Some(&1));
        assert!(
            snapshot_three
                .delegator_rewards
                .get(&validator)
                .is_none_or(|rewards| u256_from_big_endian(rewards).is_zero())
        );
        assert_eq!(
            balance_of(&final_chain, validator),
            validator_balance_before + U256::from(645u64)
        );

        drop(final_chain);
        let final_chain = FinalChain::new_with_rewards_config(
            storage.clone(),
            200_000,
            0,
            vec![genesis_account(validator, U256::from(2_000_000u64))],
            vec![genesis_validator],
            genesis_dpos_config,
            rewards_config,
        )
        .unwrap();
        let snapshot_three_after_restart = final_chain.dpos_snapshot(period_three).unwrap();
        assert_eq!(
            u256_from_big_endian(
                snapshot_three_after_restart
                    .total_stakes
                    .get(&validator)
                    .expect("missing restart validator stake"),
            ),
            U256::from(16_000u64)
        );
        assert_eq!(snapshot_three_after_restart.total_vote_count, 1);
        assert_eq!(
            snapshot_three_after_restart.vote_counts.get(&validator),
            Some(&1)
        );
        assert!(
            snapshot_three_after_restart
                .delegator_rewards
                .get(&validator)
                .is_none_or(|rewards| u256_from_big_endian(rewards).is_zero())
        );
        assert_eq!(
            balance_of(&final_chain, validator),
            validator_balance_before + U256::from(645u64)
        );
        let mut snapshot_one_after_restart = final_chain.dpos_snapshot(period_one).unwrap();
        let mut accounts_after_restart = final_chain.current_account_snapshot().unwrap();
        let err = final_chain
            .apply_dpos_redelegate(
                &mut snapshot_one_after_restart,
                &mut accounts_after_restart,
                validator,
                validator,
                validator,
                u256_to_big_endian(U256::from(1_000u64)),
                period_one,
            )
            .unwrap_err();
        assert!(
            err.to_string()
                .contains("repeated reward-bearing same-validator redelegation")
        );
        assert!(
            snapshot_three_after_restart
                .redelegate_same_validator_corruption
                .contains(&validator)
        );

        drop(storage);
        let _ = std::fs::remove_dir_all(path);
    }

